void print_right_triangle(int rows) {
    for (int i = 1; i <= rows; i++) {
        for (int j = 1; j <= i; j++) {
            putchar('*');
        }
        putchar('\n');
    }
}

void print_pyramid(int rows) {
    for (int i = 1; i <= rows; i++) {
        for (int s = 0; s < rows - i; s++) {
            putchar(' ');
        }
        for (int j = 0; j < (2 * i - 1); j++) {
            putchar('*');
        }
        putchar('\n');
    }
}

void print_diamond(int n) {
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s < n - i; s++) putchar(' ');
        for (int j = 0; j < (2 * i - 1); j++) putchar('*');
        putchar('\n');
    }
    for (int i = n - 1; i >= 1; i--) {
        for (int s = 0; s < n - i; s++) putchar(' ');
        for (int j = 0; j < (2 * i - 1); j++) putchar('*');
        putchar('\n');
    }
}

void print_hollow_square(int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            if (i == 0 || i == size - 1 || j == 0 || j == size - 1) {
                putchar('*');
            } else {
                putchar(' ');
            }
        }
        putchar('\n');
    }
}

void swap_ints(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void apply_mapper(int* arr, int size, IntMapper fn) {
    for (int i = 0; i < size; i++) {
        arr[i] = fn(arr[i]);
    }
}

long long factorial(int n) {
    if (n <= 1) return 1;
    return (long long)n * factorial(n - 1);
}

long long fibonacci(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

long long power_recursive(long long base, int exp) {
    if (exp <= 0) return 1;
    if (exp % 2 == 0) {
        long long half = power_recursive(base, exp / 2);
        return half * half;
    }
    return base * power_recursive(base, exp - 1);
}

int sum_digits(int n) {
    if (n < 0) n = -n;
    if (n == 0) return 0;
    return (n % 10) + sum_digits(n / 10);
}

void rebind_ptr(int** ptr, int* new_target) {
    if (ptr != NULL) {
        *ptr = new_target;
    }
}

size_t ptr_strlen(const char* s) {
    const char* p = s;
    while (*p != '\0') {
        p++;
    }
