}

int* alloc_int_array(size_t count) {
    int* arr = (int*)malloc(count * sizeof(int));
    return arr;
}

int* alloc_zero_array(size_t count) {
    int* arr = (int*)calloc(count, sizeof(int));
    return arr;
}

int* grow_int_array(int* arr, size_t* capacity) {
    size_t new_cap = (*capacity == 0) ? 8 : (*capacity * 2);
    int* next = (int*)realloc(arr, new_cap * sizeof(int));
    if (next != NULL) {
        *capacity = new_cap;
    }
    return next;
}

void safe_free(void** ptr) {
    if (ptr != NULL && *ptr != NULL) {
        free(*ptr);
        *ptr = NULL;
    }
}

typedef struct Person {
    char name[64];
    int age;
    float score;
} Person;

Person* create_person(const char* name, int age, float score) {
    Person* p = (Person*)malloc(sizeof(Person));
    if (!p) return NULL;
    strncpy(p->name, name, sizeof(p->name) - 1);
    p->name[sizeof(p->name) - 1] = '\0';
    p->age = age;
    p->score = score;
    return p;
}

void print_person(const Person* p) {
    if (!p) return;
    printf("Person { name: %s, age: %d, score: %.2f }\n", p->name, p->age, p->score);
}

void free_person(Person** p) {
    if (p != NULL && *p != NULL) {
        free(*p);
        *p = NULL;
    }
}

typedef struct Point2D {
    double x;
    double y;
} Point2D;

double point2d_distance(const Point2D* a, const Point2D* b) {
    double dx = a->x - b->x;
    double dy = a->y - b->y;
    return sqrt(dx * dx + dy * dy);
}

