FILE* open_file_read(const char* filepath) {
    FILE* f = fopen(filepath, "r");
    return f;
}

int read_file_lines(const char* path, char lines[][256], int max_lines) {
    FILE* f = fopen(path, "r");
    if (!f) return -1;
    int count = 0;
    while (count < max_lines && fgets(lines[count], 256, f) != NULL) {
        lines[count][strcspn(lines[count], "\n")] = '\0';
        count++;
    }
    fclose(f);
    return count;
}

int write_file_text(const char* path, const char* text) {
    FILE* f = fopen(path, "w");
    if (!f) return -1;
    fputs(text, f);
    fclose(f);
    return 0;
}

int append_file_text(const char* path, const char* text) {
    FILE* f = fopen(path, "a");
    if (!f) return -1;
    fputs(text, f);
    fclose(f);
    return 0;
}

size_t write_binary_records(const char* path, const void* records, size_t size, size_t count) {
    FILE* f = fopen(path, "wb");
    if (!f) return 0;
    size_t written = fwrite(records, size, count, f);
    fclose(f);
    return written;
}

int string_length(const char* s) {
    int len = 0;
    while (s[len] != '\0') {
        len++;
    }
    return len;
}

void string_copy(char* dest, const char* src) {
    int i = 0;
    while (src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }
    dest[i] = '\0';
}

void string_concat(char* dest, const char* src) {
    int i = 0;
    while (dest[i] != '\0') i++;
    int j = 0;
    while (src[j] != '\0') {
        dest[i++] = src[j++];
    }
    dest[i] = '\0';
}

int string_compare(const char* s1, const char* s2) {
    int i = 0;
    while (s1[i] != '\0' && s2[i] != '\0') {
        if (s1[i] != s2[i]) {
            return (unsigned char)s1[i] - (unsigned char)s2[i];
        }
        i++;
    }
    return (unsigned char)s1[i] - (unsigned char)s2[i];
}

void string_reverse(char* s) {
    int i = 0;
    while (s[i] != '\0') i++;
    int left = 0, right = i - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

void string_to_lower(char* s) {
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') {
            s[i] = (char)(s[i] + 32);
        }
    }
}

void string_to_upper(char* s) {
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (char)(s[i] - 32);
        }
    }
}

int string_substring(const char* src, int start, int len, char* dest) {
    int src_len = 0;
    while (src[src_len] != '\0') src_len++;
    if (start < 0 || start >= src_len || len < 0) {
        dest[0] = '\0';
        return 0;
    }
    int i = 0;
    while (i < len && src[start + i] != '\0') {
        dest[i] = src[start + i];
        i++;
    }
    dest[i] = '\0';
    return i;
}

int string_find(const char* haystack, const char* needle) {
    if (needle[0] == '\0') return 0;
    for (int i = 0; haystack[i] != '\0'; i++) {
        int j = 0;
        while (haystack[i + j] != '\0' && needle[j] != '\0' && haystack[i + j] == needle[j]) {
            j++;
        }
        if (needle[j] == '\0') return i;
    }
    return -1;
}

void string_trim(char* s) {
    int start = 0;
    while (s[start] == ' ' || s[start] == '\t' || s[start] == '\n' || s[start] == '\r') {
        start++;
    }
    int end = start;
    while (s[end] != '\0') end++;
    end--;
    while (end >= start && (s[end] == ' ' || s[end] == '\t' || s[end] == '\n' || s[end] == '\r')) {
        end--;
    }
    int i = 0;
    for (int j = start; j <= end; j++) {
        s[i++] = s[j];
    }
    s[i] = '\0';
}

int string_word_count(const char* s) {
    int count = 0;
    int in_word = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == ' ' || s[i] == '\t' || s[i] == '\n') {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            count++;
        }
    }
    return count;
}

void string_from_int(int val, char* dest) {
    if (val == 0) {
        dest[0] = '0';
        dest[1] = '\0';
        return;
    }
    int is_neg = 0;
    if (val < 0) {
        is_neg = 1;
        val = -val;
    }
    char buf[16];
    int idx = 0;
    while (val > 0) {
        buf[idx++] = (char)('0' + (val % 10));
        val /= 10;
    }
    int o = 0;
    if (is_neg) dest[o++] = '-';
    while (idx > 0) {
        dest[o++] = buf[--idx];
    }
    dest[o] = '\0';
}

int string_to_int(const char* s, int* out_val) {
    int i = 0;
    while (s[i] == ' ' || s[i] == '\t') i++;
    int sign = 1;
    if (s[i] == '-') {
        sign = -1;
        i++;
    } else if (s[i] == '+') {
        i++;
    }
    if (s[i] < '0' || s[i] > '9') return 0;
    int res = 0;
    while (s[i] >= '0' && s[i] <= '9') {
        res = res * 10 + (s[i] - '0');
        i++;
    }
    *out_val = res * sign;
    return 1;
}

