static unsigned long long memo[93];
static long long recursive_calls = 0;

static unsigned long long fib_memo(int n) {
    recursive_calls++;
    if (n <= 0) return 0;
    if (n == 1) return 1;
    if (memo[n] != 0) return memo[n];
    memo[n] = fib_memo(n - 1) + fib_memo(n - 2);
    return memo[n];
}

