            if (scanf("%d", &n) == 1 && n >= 0 && n <= 90) {
                memset(memo, 0, sizeof(memo));
                recursive_calls = 0;
                unsigned long long result = fib_memo(n);
                printf("Fibonacci(%d) = %llu\n", n, result);
                printf("Memoized recursive calls made: %lld\n", recursive_calls);
            }
        } else if (choice == 2) {
