#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

static double apply_op(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return (b != 0.0) ? a / b : 0.0;
        default:  return 0.0;
    }
}

static double eval_postfix(const char* expr) {
    double values[64];
    int v_top = -1;
    char ops[64];
    int o_top = -1;

    for (int i = 0; expr[i] != '\0'; i++) {
        if (isspace((unsigned char)expr[i])) continue;

        if (isdigit((unsigned char)expr[i])) {
            double val = 0;
            while (i < (int)strlen(expr) && isdigit((unsigned char)expr[i])) {
                val = (val * 10) + (expr[i] - '0');
                i++;
            }
            i--;
            values[++v_top] = val;
        } else if (expr[i] == '(') {
            ops[++o_top] = expr[i];
        } else if (expr[i] == ')') {
            while (o_top >= 0 && ops[o_top] != '(') {
                double val2 = values[v_top--];
                double val1 = values[v_top--];
                char op = ops[o_top--];
                values[++v_top] = apply_op(val1, val2, op);
            }
            if (o_top >= 0) o_top--;
        } else {
            while (o_top >= 0 && precedence(ops[o_top]) >= precedence(expr[i])) {
                double val2 = values[v_top--];
                double val1 = values[v_top--];
                char op = ops[o_top--];
                values[++v_top] = apply_op(val1, val2, op);
            }
            ops[++o_top] = expr[i];
        }
    }

    while (o_top >= 0) {
        double val2 = values[v_top--];
        double val1 = values[v_top--];
        char op = ops[o_top--];
        values[++v_top] = apply_op(val1, val2, op);
    }

    return (v_top >= 0) ? values[v_top] : 0.0;
}

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

int main(void) {
    char expr[128];
    int choice;

    do {
        printf("\n=== SHUNTING-YARD EXPRESSION EVALUATOR ===\n");
        printf("1. Evaluate Arithmetic Expression\n");
        printf("0. Exit\n");
        printf("Select option: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            continue;
        }
        clear_input();

        if (choice == 1) {
            printf("Enter infix expression (e.g. 3 + 5 * ( 2 - 8 )): ");
            if (fgets(expr, sizeof(expr), stdin)) {
                expr[strcspn(expr, "\r\n")] = '\0';
                if (strlen(expr) > 0) {
                    double ans = eval_postfix(expr);
                    printf("Result: %.4f\n", ans);
                }
            }
        }
    } while (choice != 0);

    return 0;
}

#include <stdio.h>
#include <string.h>
