                for (int c = 0; c < 2; c++) {
                    if (scanf("%lf", &a.data[r][c]) != 1) a.data[r][c] = 0.0;
                }
            }
        }
        clear_input();
    } while (choice != 0);

    return 0;
}

void array_1d_reverse(int* arr, int n) {
    int start = 0, end = n - 1;
    while (start < end) {
        int tmp = arr[start];
        arr[start] = arr[end];
        arr[end] = tmp;
        start++;
        end--;
    }
}

void array_1d_rotate(int* arr, int n, int k) {
    if (n <= 0) return;
    k = k % n;
    if (k < 0) k += n;
    for (int i = 0; i < k; i++) {
        int first = arr[0];
        for (int j = 0; j < n - 1; j++) {
            arr[j] = arr[j + 1];
        }
        arr[n - 1] = first;
    }
}

int array_1d_binary_search(const int* arr, int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

void array_1d_min_max(const int* arr, int n, int* min_val, int* max_val) {
    if (n <= 0) return;
    *min_val = arr[0];
    *max_val = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < *min_val) *min_val = arr[i];
        if (arr[i] > *max_val) *max_val = arr[i];
    }
}

typedef struct Matrix2D {
    int rows;
    int cols;
    int** data;
} Matrix2D;

Matrix2D* matrix_2d_alloc(int rows, int cols) {
    Matrix2D* m = (Matrix2D*)malloc(sizeof(Matrix2D));
    if (!m) return NULL;
    m->rows = rows;
    m->cols = cols;
    m->data = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        m->data[i] = (int*)calloc(cols, sizeof(int));
    }
    return m;
}

void matrix_2d_free(Matrix2D* m) {
    if (!m) return;
    for (int i = 0; i < m->rows; i++) {
        free(m->data[i]);
    }
    free(m->data);
    free(m);
}

Matrix2D* matrix_2d_transpose(const Matrix2D* src) {
    if (!src) return NULL;
    Matrix2D* t = matrix_2d_alloc(src->cols, src->rows);
    if (!t) return NULL;
    for (int i = 0; i < src->rows; i++) {
        for (int j = 0; j < src->cols; j++) {
            t->data[j][i] = src->data[i][j];
        }
    }
    return t;
}

typedef struct Tensor3D {
    int d1;
    int d2;
    int d3;
    int* data;
} Tensor3D;

Tensor3D* tensor_3d_alloc(int d1, int d2, int d3) {
    Tensor3D* t = (Tensor3D*)malloc(sizeof(Tensor3D));
    if (!t) return NULL;
    t->d1 = d1;
    t->d2 = d2;
    t->d3 = d3;
    t->data = (int*)calloc(d1 * d2 * d3, sizeof(int));
    return t;
}

void tensor_3d_set(Tensor3D* t, int i, int j, int k, int val) {
    if (i >= 0 && i < t->d1 && j >= 0 && j < t->d2 && k >= 0 && k < t->d3) {
        int idx = (i * t->d2 * t->d3) + (j * t->d3) + k;
        t->data[idx] = val;
    }
}

void tensor_3d_free(Tensor3D* t) {
    if (!t) return;
    free(t->data);
    free(t);
}

typedef struct Vector {
    int* items;
    size_t size;
    size_t capacity;
} Vector;

Vector* vector_init(size_t initial_cap) {
    Vector* v = (Vector*)malloc(sizeof(Vector));
    if (!v) return NULL;
    v->capacity = (initial_cap == 0) ? 4 : initial_cap;
    v->size = 0;
    v->items = (int*)malloc(v->capacity * sizeof(int));
    return v;
}

void vector_push_back(Vector* v, int val) {
    if (v->size >= v->capacity) {
        v->capacity *= 2;
        v->items = (int*)realloc(v->items, v->capacity * sizeof(int));
    }
    v->items[v->size++] = val;
}

int vector_pop_back(Vector* v) {
    if (v->size == 0) return 0;
    return v->items[--v->size];
}

void vector_free(Vector* v) {
    if (!v) return;
    free(v->items);
    free(v);
}

typedef struct Node {
    int data;
    struct Node* next;
} Node;
typedef Node SinglyNode;

Node* createNode(int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = data;
    n->next = NULL;
    return n;
}

void singly_insert_head(Node** head, int data) {
    Node* n = createNode(data);
    if (!n) return;
    n->next = *head;
    *head = n;
}

void singly_insert_tail(Node** head, int data) {
    Node* n = createNode(data);
    if (!n) return;
    if (*head == NULL) {
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next != NULL) {
        cur = cur->next;
    }
    cur->next = n;
}

void singly_insert_after(Node* target, int data) {
    if (!target) return;
    Node* n = createNode(data);
    if (!n) return;
    n->next = target->next;
    target->next = n;
}

void singly_insert_before(Node** head, int target_val, int data) {
    if (!head || !*head) return;
    if ((*head)->data == target_val) {
        singly_insert_head(head, data);
        return;
    }
    Node* cur = *head;
    while (cur->next && cur->next->data != target_val) {
        cur = cur->next;
    }
    if (cur->next) {
        Node* n = createNode(data);
        if (!n) return;
        n->next = cur->next;
        cur->next = n;
    }
}

int singly_delete_value(Node** head, int val) {
    if (!head || !*head) return 0;
    Node* cur = *head;
    if (cur->data == val) {
        *head = cur->next;
        free(cur);
        return 1;
    }
    while (cur->next && cur->next->data != val) {
        cur = cur->next;
    }
    if (cur->next) {
        Node* del = cur->next;
        cur->next = del->next;
        free(del);
        return 1;
    }
    return 0;
}

