int array_stack_push(ArrayStack* s, int val) {
    if (s->top >= s->capacity - 1) {
        s->capacity *= 2;
        s->data = (int*)realloc(s->data, s->capacity * sizeof(int));
    }
    s->data[++s->top] = val;
    return 1;
}

int array_stack_pop(ArrayStack* s, int* val) {
    if (s->top < 0) return 0;
