void mono_stack_next_greater(const int* arr, int n, int* result) {
    int* stack = (int*)malloc(n * sizeof(int));
    int top = -1;
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && stack[top] <= arr[i]) {
            top--;
        }
        result[i] = (top < 0) ? -1 : stack[top];
        stack[++top] = arr[i];
    }
    free(stack);
}

typedef struct LinearQueue {
    int* data;
