    int capacity;
} LinearQueue;

int linear_queue_enqueue(LinearQueue* q, int val) {
    if (q->rear >= q->capacity - 1) return 0;
    q->data[++q->rear] = val;
    return 1;
}

int linear_queue_dequeue(LinearQueue* q, int* val) {
    if (q->front > q->rear) return 0;
    *val = q->data[q->front++];
    return 1;
}

typedef struct CircularQueue {
    int* data;
    int front;
    int rear;
    int size;
    int capacity;
} CircularQueue;

int circular_queue_enqueue(CircularQueue* q, int val) {
    if (q->size == q->capacity) return 0;
    q->rear = (q->rear + 1) % q->capacity;
    q->data[q->rear] = val;
    q->size++;
    return 1;
}

int circular_queue_dequeue(CircularQueue* q, int* val) {
    if (q->size == 0) return 0;
    *val = q->data[q->front];
    q->front = (q->front + 1) % q->capacity;
    q->size--;
    return 1;
}

