int deque_push_front(Deque* d, int val) {
    if (d->size == d->capacity) return 0;
    d->front = (d->front - 1 + d->capacity) % d->capacity;
    d->data[d->front] = val;
    d->size++;
    return 1;
}

int deque_push_back(Deque* d, int val) {
    if (d->size == d->capacity) return 0;
    d->rear = (d->rear + 1) % d->capacity;
    d->data[d->rear] = val;
    d->size++;
