}

typedef struct PriorityQueue {
    int* data;
    int size;
    int capacity;
} PriorityQueue;

void pq_push(PriorityQueue* pq, int val) {
    if (pq->size >= pq->capacity) {
        pq->capacity *= 2;
        pq->data = (int*)realloc(pq->data, pq->capacity * sizeof(int));
    }
    int i = pq->size++;
    pq->data[i] = val;
    while (i != 0 && pq->data[(i - 1) / 2] > pq->data[i]) {
        int tmp = pq->data[i];
        pq->data[i] = pq->data[(i - 1) / 2];
        pq->data[(i - 1) / 2] = tmp;
        i = (i - 1) / 2;
    }
}

int pq_pop(PriorityQueue* pq, int* min_val) {
    if (pq->size <= 0) return 0;
    *min_val = pq->data[0];
    pq->data[0] = pq->data[--pq->size];
    int i = 0;
    while (2 * i + 1 < pq->size) {
        int smallest = i;
        int l = 2 * i + 1;
        int r = 2 * i + 2;
        if (l < pq->size && pq->data[l] < pq->data[smallest]) smallest = l;
        if (r < pq->size && pq->data[r] < pq->data[smallest]) smallest = r;
        if (smallest == i) break;
        int tmp = pq->data[i];
        pq->data[i] = pq->data[smallest];
        pq->data[smallest] = tmp;
        i = smallest;
    }
    return 1;
}

