static unsigned long chain_hash_fn_search(const char* s, int mod) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) h = ((h << 5) + h) + c;
    return h % mod;
}

int chain_hash_search(const ChainHashTable* ht, const char* key, int* val) {
    unsigned long b = chain_hash_fn_search(key, ht->size);
    Node* cur = ht->buckets[b];
    while (cur) {
        if (strcmp(cur->key, key) == 0) {
            *val = cur->value;
            return 1;
        }
        cur = cur->next;
    }
    return 0;
}

static unsigned long chain_hash_fn_del(const char* s, int mod) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) h = ((h << 5) + h) + c;
    return h % mod;
}

int chain_hash_delete(ChainHashTable* ht, const char* key, int* val) {
    unsigned long b = chain_hash_fn_del(key, ht->size);
    Node* cur = ht->buckets[b];
    Node* prev = NULL;
    while (cur) {
        if (strcmp(cur->key, key) == 0) {
            *val = cur->value;
            if (prev) prev->next = cur->next;
            else ht->buckets[b] = cur->next;
            free(cur);
            return 1;
        }
        prev = cur;
        cur = cur->next;
    }
    return 0;
}

float chain_hash_load_factor(const ChainHashTable* ht) {
    if (ht->size == 0) return 0.0f;
    int items = 0;
    for (int i = 0; i < ht->size; i++) {
        Node* cur = ht->buckets[i];
        while (cur) {
            items++;
            cur = cur->next;
        }
    }
    return (float)items / ht->size;
}

static unsigned long open_hash_calc_s(const char* s, int mod) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) h = ((h << 5) + h) + c;
    return h % mod;
}

int open_hash_search(const OpenHashTable* ht, const char* key, int* val) {
    unsigned long idx = open_hash_calc_s(key, ht->capacity);
    for (int i = 0; i < ht->capacity; i++) {
        int pos = (idx + i) % ht->capacity;
        if (!ht->entries[pos].occupied) return 0;
        if (strcmp(ht->entries[pos].key, key) == 0) {
            *val = ht->entries[pos].value;
            return 1;
        }
    }
    return 0;
}

static unsigned long open_hash_calc_d(const char* s, int mod) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) h = ((h << 5) + h) + c;
    return h % mod;
}

int open_hash_delete(OpenHashTable* ht, const char* key, int* val) {
    unsigned long idx = open_hash_calc_d(key, ht->capacity);
    for (int i = 0; i < ht->capacity; i++) {
        int pos = (idx + i) % ht->capacity;
        if (!ht->entries[pos].occupied) return 0;
        if (strcmp(ht->entries[pos].key, key) == 0) {
            *val = ht->entries[pos].value;
            ht->entries[pos].occupied = false;
            ht->count--;
            return 1;
        }
    }
    return 0;
}

unsigned long hash_sdbm(const char* str) {
    unsigned long hash = 0;
    int c;
    while ((c = (unsigned char)*str++)) {
        hash = c + (hash << 6) + (hash << 16) - hash;
    }
    return hash;
}

uint32_t hash_murmur32(const char* key, uint32_t seed) {
    uint32_t h = seed;
    uint32_t k;
    size_t len = strlen(key);
    const uint8_t* data = (const uint8_t*)key;
    const size_t nblocks = len / 4;
    for (size_t i = 0; i < nblocks; i++) {
        k = (uint32_t)data[i*4] | ((uint32_t)data[i*4+1] << 8) |
            ((uint32_t)data[i*4+2] << 16) | ((uint32_t)data[i*4+3] << 24);
        k *= 0xcc9e2d51;
        k = (k << 15) | (k >> 17);
        k *= 0x1b873593;
        h ^= k;
        h = (h << 13) | (h >> 19);
        h = h * 5 + 0xe6546b64;
    }
    k = 0;
    const uint8_t* tail = data + (nblocks * 4);
    switch (len & 3) {
        case 3: k ^= (uint32_t)tail[2] << 16;
        case 2: k ^= (uint32_t)tail[1] << 8;
        case 1: k ^= (uint32_t)tail[0];
                k *= 0xcc9e2d51;
                k = (k << 15) | (k >> 17);
                k *= 0x1b873593;
                h ^= k;
    }
    h ^= (uint32_t)len;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    h *= 0xc2b2ae35;
    h ^= h >> 16;
    return h;
}

uint64_t hash_polynomial(const char* str) {
    const int p = 31;
    const uint64_t m = 1000000009;
    uint64_t hash_val = 0;
    uint64_t p_pow = 1;
    while (*str) {
        hash_val = (hash_val + (*str - 'a' + 1) * p_pow) % m;
        p_pow = (p_pow * p) % m;
        str++;
    }
    return hash_val;
}

