    Node* n = create_node(data);
    if (!n) return false;
    n->next = cur->next;
    cur->next = n;
    return true;
}

void insert_sorted(Node** head, int data) {
    Node* n = create_node(data);
    if (!n) return;
    if (!*head || (*head)->data >= data) {
        n->next = *head;
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next && cur->next->data < data) {
        cur = cur->next;
    }
    n->next = cur->next;
    cur->next = n;
}

bool delete_beginning(Node** head, int* val) {
    if (!*head) return false;
    Node* tmp = *head;
    *val = tmp->data;
    *head = (*head)->next;
    free(tmp);
