    while (cur) {
        printf("%d -> ", cur->data);
        count++;
        cur = cur->next;
    }
    printf("NULL (total: %d)\n", count);
}

void free_list(Node** head) {
    Node* cur = *head;
    while (cur) {
        Node* nxt = cur->next;
        free(cur);
        cur = nxt;
    }
    *head = NULL;
}

