void reverse_list(Node** head) {
    if (!*head) return;
    Node* cur = *head;
    Node* tmp = NULL;
    while (cur) {
        tmp = cur->prev;
        cur->prev = cur->next;
        cur->next = tmp;
        cur = cur->prev;
    }
    if (tmp) *head = tmp->prev;
