} Node;

Node* create_node(int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = data;
    n->next = n;
    return n;
}

void insert_beginning(Node** head, int data) {
    Node* n = create_node(data);
    if (!n) return;
    if (!*head) {
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next != *head) cur = cur->next;
    n->next = *head;
    cur->next = n;
    *head = n;
}

void insert_end(Node** head, int data) {
    Node* n = create_node(data);
    if (!n) return;
    if (!*head) {
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next != *head) cur = cur->next;
    cur->next = n;
    n->next = *head;
}

int count_nodes(const Node* head) {
    if (!head) return 0;
    int cnt = 0;
    const Node* cur = head;
    do {
        cnt++;
        cur = cur->next;
    } while (cur != head);
    return cnt;
}

bool insert_at_position(Node** head, int pos, int data) {
    int total = count_nodes(*head);
    if (pos < 1 || pos > total + 1) return false;
    if (pos == 1) {
        insert_beginning(head, data);
        return true;
    }
    if (pos == total + 1) {
        insert_end(head, data);
        return true;
    }
    Node* cur = *head;
    for (int i = 1; i < pos - 1; i++) cur = cur->next;
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return false;
    n->data = data;
    n->next = cur->next;
    cur->next = n;
    return true;
}

bool insert_before_value(Node** head, int target, int data) {
    if (!head || !*head) return false;
    if ((*head)->data == target) {
        insert_beginning(head, data);
        return true;
    }
    Node* cur = *head;
    while (cur->next != *head && cur->next->data != target) cur = cur->next;
    if (cur->next != *head && cur->next->data == target) {
        Node* n = (Node*)malloc(sizeof(Node));
        if (!n) return false;
        n->data = data;
        n->next = cur->next;
        cur->next = n;
        return true;
    }
    return false;
}

bool insert_after_value(Node* head, int target, int data) {
    if (!head) return false;
    Node* cur = head;
    do {
        if (cur->data == target) {
            Node* n = (Node*)malloc(sizeof(Node));
            if (!n) return false;
            n->data = data;
            n->next = cur->next;
            cur->next = n;
            return true;
        }
        cur = cur->next;
    } while (cur != head);
    return false;
}

void insert_sorted(Node** head, int data) {
    Node* n = create_node(data);
    if (!n) return;
    if (!*head) {
        *head = n;
        return;
    }
    if (data <= (*head)->data) {
        Node* last = *head;
        while (last->next != *head) last = last->next;
        n->next = *head;
        last->next = n;
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next != *head && cur->next->data < data) cur = cur->next;
    n->next = cur->next;
    cur->next = n;
}

bool delete_beginning(Node** head, int* val) {
    if (!*head) return false;
    *val = (*head)->data;
    if ((*head)->next == *head) {
        free(*head);
        *head = NULL;
        return true;
    }
    Node* last = *head;
    while (last->next != *head) last = last->next;
    Node* tmp = *head;
    *head = (*head)->next;
    last->next = *head;
    free(tmp);
    return true;
}

bool delete_end(Node** head, int* val) {
    if (!*head) return false;
    if ((*head)->next == *head) {
        *val = (*head)->data;
        free(*head);
        *head = NULL;
        return true;
    }
    Node* prev = NULL;
    Node* cur = *head;
    while (cur->next != *head) {
        prev = cur;
        cur = cur->next;
    }
    *val = cur->data;
    prev->next = *head;
    free(cur);
    return true;
}

bool delete_at_position(Node** head, int pos, int* val) {
    int total = count_nodes(*head);
    if (pos < 1 || pos > total) return false;
    if (pos == 1) return delete_beginning(head, val);
    Node* prev = *head;
    for (int i = 1; i < pos - 1; i++) prev = prev->next;
    Node* cur = prev->next;
    *val = cur->data;
    prev->next = cur->next;
    free(cur);
    return true;
}

bool delete_by_value(Node** head, int val) {
    if (!*head) return false;
    if ((*head)->data == val) {
        int dummy;
        return delete_beginning(head, &dummy);
    }
    Node* prev = *head;
    Node* cur = (*head)->next;
    while (cur != *head && cur->data != val) {
        prev = cur;
        cur = cur->next;
    }
    if (cur != *head) {
        prev->next = cur->next;
        free(cur);
        return true;
    }
    return false;
}

bool delete_after_value(Node** head, int target, int* val) {
    if (!*head) return false;
    Node* cur = *head;
    do {
        if (cur->data == target) {
            if (cur->next == *head) {
                return delete_beginning(head, val);
            }
            Node* del = cur->next;
            *val = del->data;
            cur->next = del->next;
            free(del);
            return true;
        }
        cur = cur->next;
    } while (cur != *head);
    return false;
}

int search_element(const Node* head, int val) {
    if (!head) return -1;
    const Node* cur = head;
    int pos = 1;
    do {
        if (cur->data == val) return pos;
        cur = cur->next;
        pos++;
    } while (cur != head);
    return -1;
}

void reverse_list(Node** head) {
    if (!*head || (*head)->next == *head) return;
    Node* prev = NULL;
    Node* cur = *head;
    Node* nxt = NULL;
    do {
        nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    } while (cur != *head);
    (*head)->next = prev;
    *head = prev;
}

void sort_list(Node* head) {
    if (!head || head->next == head) return;
    int swapped;
    do {
        swapped = 0;
        Node* cur = head;
        while (cur->next != head) {
            if (cur->data > cur->next->data) {
                int tmp = cur->data;
                cur->data = cur->next->data;
                cur->next->data = tmp;
                swapped = 1;
            }
            cur = cur->next;
        }
    } while (swapped);
}

void remove_duplicates(Node* head) {
    if (!head || head->next == head) return;
    Node* cur = head;
    do {
        Node* prev = cur;
        Node* runner = cur->next;
        while (runner != head) {
            if (runner->data == cur->data) {
                prev->next = runner->next;
                free(runner);
                runner = prev->next;
            } else {
                prev = runner;
                runner = runner->next;
            }
        }
        cur = cur->next;
    } while (cur != head && cur->next != head);
}

bool find_middle(const Node* head, int* val) {
    if (!head) return false;
    const Node* slow = head;
    const Node* fast = head;
    while (fast->next != head && fast->next->next != head) {
        slow = slow->next;
        fast = fast->next->next;
    }
    *val = slow->data;
    return true;
}

bool min_and_max(const Node* head, int* min_val, int* max_val) {
    if (!head) return false;
    *min_val = head->data;
    *max_val = head->data;
    const Node* cur = head->next;
    while (cur != head) {
        if (cur->data < *min_val) *min_val = cur->data;
        if (cur->data > *max_val) *max_val = cur->data;
        cur = cur->next;
    }
    return true;
}

void split_halves(Node* head, Node** head1, Node** head2) {
    *head1 = NULL;
    *head2 = NULL;
    if (!head) return;
    Node* slow = head;
    Node* fast = head;
    while (fast->next != head && fast->next->next != head) {
        slow = slow->next;
        fast = fast->next->next;
    }
    if (fast->next->next == head) fast = fast->next;
    *head1 = head;
    if (head->next != head) *head2 = slow->next;
    fast->next = slow->next;
    slow->next = head;
}

void display_list_and_count(const Node* head) {
    if (!head) {
        printf("Circular list is empty (count: 0)\n");
        return;
    }
    printf("Circular List: ");
    const Node* cur = head;
    int cnt = 0;
    do {
        printf("%d -> ", cur->data);
        cnt++;
        cur = cur->next;
    } while (cur != head);
    printf("(head: %d) [total: %d]\n", head->data, cnt);
}

void free_list(Node** head) {
    if (!*head) return;
    Node* cur = *head;
    Node* last = *head;
    while (last->next != *head) last = last->next;
    last->next = NULL;
    while (cur) {
        Node* nxt = cur->next;
        free(cur);
        cur = nxt;
    }
    *head = NULL;
}

