                printf("Leaf Nodes Count: %d\n", count_leaf_nodes(root));
                break;
            case 19:
                mirror_tree(root);
                printf("Tree mirrored successfully. New inorder: ");
                inorder(root);
                printf("\n");
                break;
            case 0:
                printf("Exiting BST program.\n");
                break;
            default:
                printf("Invalid option! Please choose between 0 and 19.\n");
                break;
        }
    } while (choice != 0);

    free_tree(root);
    return 0;
}

#include <stdio.h>
