void bubble_sort(int* arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        int swapped = 0;
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int tmp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = tmp;
                swapped = 1;
            }
        }
        if (!swapped) break;
    }
}

void selection_sort(int* arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        if (min_idx != i) {
            int tmp = arr[i];
            arr[i] = arr[min_idx];
            arr[min_idx] = tmp;
        }
    }
}

void insertion_sort(int* arr, int n) {
    for (int i = 1; i < n; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

int quick_sort_lomuto_partition(int* arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }
    }
    int tmp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = tmp;
    return i + 1;
}

void quick_sort(int* arr, int low, int high) {
    if (low < high) {
        int pi = quick_sort_lomuto_partition(arr, low, high);
        quick_sort(arr, low, pi - 1);
        quick_sort(arr, pi + 1, high);
    }
}

void merge_sorted_subarrays(int* arr, int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;
    int* left = (int*)malloc(n1 * sizeof(int));
    int* right = (int*)malloc(n2 * sizeof(int));
    for (int i = 0; i < n1; i++) left[i] = arr[l + i];
    for (int j = 0; j < n2; j++) right[j] = arr[m + 1 + j];
    int i = 0, j = 0, k = l;
    while (i < n1 && j < n2) {
        if (left[i] <= right[j]) arr[k++] = left[i++];
        else arr[k++] = right[j++];
    }
    while (i < n1) arr[k++] = left[i++];
    while (j < n2) arr[k++] = right[j++];
    free(left);
    free(right);
}

void merge_sort(int* arr, int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        merge_sort(arr, l, m);
        merge_sort(arr, m + 1, r);
        merge_sorted_subarrays(arr, l, m, r);
    }
}

void max_heapify_down(int* arr, int n, int i) {
    int largest = i;
    int l = 2 * i + 1;
    int r = 2 * i + 2;
    if (l < n && arr[l] > arr[largest]) largest = l;
    if (r < n && arr[r] > arr[largest]) largest = r;
    if (largest != i) {
        int tmp = arr[i];
        arr[i] = arr[largest];
        arr[largest] = tmp;
        max_heapify_down(arr, n, largest);
    }
}

void heap_sort(int* arr, int n) {
    for (int i = n / 2 - 1; i >= 0; i--) {
        max_heapify_down(arr, n, i);
    }
    for (int i = n - 1; i > 0; i--) {
        int tmp = arr[0];
        arr[0] = arr[i];
        arr[i] = tmp;
        max_heapify_down(arr, i, 0);
    }
}

void counting_sort(int* arr, int n, int max_val) {
    int* count = (int*)calloc(max_val + 1, sizeof(int));
    int* output = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) count[arr[i]]++;
    for (int i = 1; i <= max_val; i++) count[i] += count[i - 1];
    for (int i = n - 1; i >= 0; i--) {
        output[count[arr[i]] - 1] = arr[i];
        count[arr[i]]--;
    }
    for (int i = 0; i < n; i++) arr[i] = output[i];
    free(count);
    free(output);
}

static void count_sort_digit(int* arr, int n, int exp) {
    int output[1024];
    int count[10] = {0};
    for (int i = 0; i < n; i++) count[(arr[i] / exp) % 10]++;
    for (int i = 1; i < 10; i++) count[i] += count[i - 1];
    for (int i = n - 1; i >= 0; i--) {
        int digit = (arr[i] / exp) % 10;
        output[count[digit] - 1] = arr[i];
        count[digit]--;
    }
    for (int i = 0; i < n; i++) arr[i] = output[i];
}

void radix_sort(int* arr, int n) {
    if (n <= 1) return;
    int max_val = arr[0];
    for (int i = 1; i < n; i++) if (arr[i] > max_val) max_val = arr[i];
    for (int exp = 1; max_val / exp > 0; exp *= 10) {
        count_sort_digit(arr, n, exp);
    }
}

int linear_search(const int* arr, int n, int target) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == target) return i;
    }
    return -1;
}

int binary_search_lower_bound(const int* arr, int n, int target) {
    int low = 0, high = n;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] >= target) high = mid;
        else low = mid + 1;
    }
    return low;
}

int binary_search_upper_bound(const int* arr, int n, int target) {
    int low = 0, high = n;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] > target) high = mid;
        else low = mid + 1;
    }
    return low;
}

int jump_search(const int* arr, int n, int target) {
    int step = (int)sqrt((double)n);
    int prev = 0;
    while (arr[(step < n ? step : n) - 1] < target) {
        prev = step;
        step += (int)sqrt((double)n);
        if (prev >= n) return -1;
    }
    while (arr[prev] < target) {
        prev++;
        if (prev == (step < n ? step : n)) return -1;
    }
    if (arr[prev] == target) return prev;
    return -1;
}

int two_sum_sorted(const int* arr, int n, int target, int* idx1, int* idx2) {
    int l = 0, r = n - 1;
    while (l < r) {
        int sum = arr[l] + arr[r];
        if (sum == target) {
            *idx1 = l;
            *idx2 = r;
            return 1;
        }
        if (sum < target) l++;
        else r--;
    }
    return 0;
}

void graph_bfs_traversal(const int* matrix, int v, int start, int* visited) {
    int* queue = (int*)malloc(v * sizeof(int));
    int front = 0, rear = 0;
    visited[start] = 1;
    queue[rear++] = start;
    while (front < rear) {
        int u = queue[front++];
        for (int i = 0; i < v; i++) {
            if (matrix[u * v + i] && !visited[i]) {
                visited[i] = 1;
                queue[rear++] = i;
            }
        }
    }
    free(queue);
}

void graph_dfs_traversal(const int* matrix, int v, int u, int* visited) {
    visited[u] = 1;
    for (int i = 0; i < v; i++) {
        if (matrix[u * v + i] && !visited[i]) {
            graph_dfs_traversal(matrix, v, i, visited);
        }
    }
}

void dijkstra_shortest_path(const int* weight_matrix, int v, int src, int* dist) {
    int* visited = (int*)calloc(v, sizeof(int));
    for (int i = 0; i < v; i++) dist[i] = 1000000000;
    dist[src] = 0;
    for (int count = 0; count < v - 1; count++) {
        int min_d = 1000000000, u = -1;
        for (int i = 0; i < v; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        for (int i = 0; i < v; i++) {
            int w = weight_matrix[u * v + i];
            if (!visited[i] && w > 0 && dist[u] + w < dist[i]) {
                dist[i] = dist[u] + w;
            }
        }
    }
    free(visited);
}

static int dsu_root(int* parent, int i) {
    if (parent[i] == i) return i;
    return parent[i] = dsu_root(parent, parent[i]);
}

int kruskal_mst(int edge_u[], int edge_v[], int edge_w[], int e, int v) {
    for (int i = 0; i < e - 1; i++) {
        for (int j = 0; j < e - i - 1; j++) {
            if (edge_w[j] > edge_w[j + 1]) {
                int tw = edge_w[j]; edge_w[j] = edge_w[j + 1]; edge_w[j + 1] = tw;
                int tu = edge_u[j]; edge_u[j] = edge_u[j + 1]; edge_u[j + 1] = tu;
                int tv = edge_v[j]; edge_v[j] = edge_v[j + 1]; edge_v[j + 1] = tv;
            }
        }
    }
    int* parent = (int*)malloc(v * sizeof(int));
    for (int i = 0; i < v; i++) parent[i] = i;
    int total_weight = 0, count = 0;
    for (int i = 0; i < e && count < v - 1; i++) {
        int ru = dsu_root(parent, edge_u[i]);
        int rv = dsu_root(parent, edge_v[i]);
        if (ru != rv) {
            parent[ru] = rv;
            total_weight += edge_w[i];
            count++;
        }
    }
    free(parent);
    return total_weight;
}

int topological_sort_kahn(const int* adj_matrix, int v, int* order) {
    int* in_degree = (int*)calloc(v, sizeof(int));
    for (int i = 0; i < v; i++) {
        for (int j = 0; j < v; j++) {
            if (adj_matrix[i * v + j]) in_degree[j]++;
        }
    }
    int* queue = (int*)malloc(v * sizeof(int));
    int front = 0, rear = 0;
    for (int i = 0; i < v; i++) {
        if (in_degree[i] == 0) queue[rear++] = i;
    }
    int count = 0;
    while (front < rear) {
        int u = queue[front++];
        order[count++] = u;
        for (int i = 0; i < v; i++) {
            if (adj_matrix[u * v + i]) {
                if (--in_degree[i] == 0) queue[rear++] = i;
            }
        }
    }
    free(in_degree);
    free(queue);
    return (count == v);
}

int kadane_max_subarray(const int* arr, int n) {
    int max_so_far = arr[0];
    int curr_max = arr[0];
    for (int i = 1; i < n; i++) {
        curr_max = (arr[i] > curr_max + arr[i]) ? arr[i] : (curr_max + arr[i]);
        if (curr_max > max_so_far) max_so_far = curr_max;
    }
    return max_so_far;
}

int climb_stairs_dp(int n) {
    if (n <= 2) return n;
    int prev2 = 1, prev1 = 2;
    for (int i = 3; i <= n; i++) {
        int cur = prev1 + prev2;
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

int knapsack_01_tabulated(int W, const int* wt, const int* val, int n) {
    int dp[128][128] = {0};
    for (int i = 1; i <= n; i++) {
        for (int w = 0; w <= W; w++) {
            if (wt[i - 1] <= w) {
                int take = val[i - 1] + dp[i - 1][w - wt[i - 1]];
                int skip = dp[i - 1][w];
                dp[i][w] = (take > skip) ? take : skip;
            } else {
                dp[i][w] = dp[i - 1][w];
            }
        }
    }
    return dp[n][W];
}

int coin_change_min_coins(const int* coins, int n, int amount) {
    int* dp = (int*)malloc((amount + 1) * sizeof(int));
    for (int i = 1; i <= amount; i++) dp[i] = 1000000;
    dp[0] = 0;
    for (int i = 1; i <= amount; i++) {
        for (int j = 0; j < n; j++) {
            if (coins[j] <= i && dp[i - coins[j]] + 1 < dp[i]) {
                dp[i] = dp[i - coins[j]] + 1;
            }
        }
    }
    int res = (dp[amount] >= 1000000) ? -1 : dp[amount];
    free(dp);
    return res;
}

int lcs_length(const char* s1, const char* s2) {
    int m = (int)strlen(s1);
    int n = (int)strlen(s2);
    int dp[128][128] = {0};
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                int top = dp[i - 1][j];
                int left = dp[i][j - 1];
                dp[i][j] = (top > left) ? top : left;
            }
        }
    }
    return dp[m][n];
}

int lis_length(const int* arr, int n) {
    if (n <= 0) return 0;
    int* dp = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) dp[i] = 1;
    int max_len = 1;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[i] > arr[j] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
        if (dp[i] > max_len) max_len = dp[i];
    }
    free(dp);
    return max_len;
}

static int min3(int a, int b, int c) {
    int m = a < b ? a : b;
    return m < c ? m : c;
}

int edit_distance_levenshtein(const char* s1, const char* s2) {
    int m = (int)strlen(s1);
    int n = (int)strlen(s2);
    int dp[128][128];
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + min3(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
            }
        }
    }
    return dp[m][n];
}

int activity_selection_greedy(const int* start, const int* finish, int n, int* selected) {
    if (n <= 0) return 0;
    int count = 0;
    selected[count++] = 0;
    int last_finish = finish[0];
    for (int i = 1; i < n; i++) {
        if (start[i] >= last_finish) {
            selected[count++] = i;
            last_finish = finish[i];
        }
    }
    return count;
}

double fractional_knapsack_greedy(int capacity, double* wt, double* val, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            double r1 = val[j] / wt[j];
            double r2 = val[j + 1] / wt[j + 1];
            if (r1 < r2) {
                double tv = val[j]; val[j] = val[j + 1]; val[j + 1] = tv;
                double tw = wt[j]; wt[j] = wt[j + 1]; wt[j + 1] = tw;
            }
        }
    }
    double total_value = 0.0;
    double rem_cap = capacity;
    for (int i = 0; i < n; i++) {
        if (wt[i] <= rem_cap) {
            rem_cap -= wt[i];
            total_value += val[i];
        } else {
            total_value += val[i] * (rem_cap / wt[i]);
            break;
        }
    }
    return total_value;
}

int job_sequencing_deadlines(int* deadline, int* profit, int n, int max_d) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (profit[j] < profit[j + 1]) {
                int tp = profit[j]; profit[j] = profit[j + 1]; profit[j + 1] = tp;
                int td = deadline[j]; deadline[j] = deadline[j + 1]; deadline[j + 1] = td;
            }
        }
    }
    int* slot = (int*)calloc(max_d + 1, sizeof(int));
    int total_profit = 0;
    for (int i = 0; i < n; i++) {
        for (int j = (deadline[i] < max_d ? deadline[i] : max_d); j > 0; j--) {
            if (!slot[j]) {
                slot[j] = 1;
                total_profit += profit[i];
                break;
            }
        }
    }
    free(slot);
    return total_profit;
}

static int is_safe(int board[][16], int row, int col, int n) {
    for (int i = 0; i < col; i++) if (board[row][i]) return 0;
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) if (board[i][j]) return 0;
    for (int i = row, j = col; j >= 0 && i < n; i++, j--) if (board[i][j]) return 0;
    return 1;
}

int n_queens_solve(int board[][16], int col, int n) {
    if (col >= n) return 1;
    for (int i = 0; i < n; i++) {
        if (is_safe(board, i, col, n)) {
            board[i][col] = 1;
            if (n_queens_solve(board, col + 1, n)) return 1;
            board[i][col] = 0;
        }
    }
    return 0;
}

int rat_in_maze_solve(int maze[][8], int x, int y, int sol[][8], int n) {
    if (x == n - 1 && y == n - 1 && maze[x][y] == 1) {
        sol[x][y] = 1;
        return 1;
    }
    if (x >= 0 && x < n && y >= 0 && y < n && maze[x][y] == 1) {
        if (sol[x][y] == 1) return 0;
        sol[x][y] = 1;
        if (rat_in_maze_solve(maze, x + 1, y, sol, n)) return 1;
        if (rat_in_maze_solve(maze, x, y + 1, sol, n)) return 1;
        sol[x][y] = 0;
        return 0;
    }
    return 0;
}

static void swap_val(int* a, int* b) { int t = *a; *a = *b; *b = t; }

void generate_permutations(int* arr, int l, int r, void (*callback)(const int*, int)) {
    if (l == r) {
        callback(arr, r + 1);
    } else {
        for (int i = l; i <= r; i++) {
            swap_val(&arr[l], &arr[i]);
            generate_permutations(arr, l + 1, r, callback);
            swap_val(&arr[l], &arr[i]);
        }
    }
}

void kmp_compute_lps(const char* pat, int m, int* lps) {
    int len = 0;
    lps[0] = 0;
    int i = 1;
    while (i < m) {
        if (pat[i] == pat[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
    }
}

int kmp_search_pattern(const char* text, const char* pat) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    if (m == 0) return 0;
    int* lps = (int*)malloc(m * sizeof(int));
    kmp_compute_lps(pat, m, lps);
    int i = 0, j = 0;
    int match_idx = -1;
    while (i < n) {
        if (pat[j] == text[i]) {
            i++;
            j++;
        }
        if (j == m) {
            match_idx = i - j;
            break;
        } else if (i < n && pat[j] != text[i]) {
            if (j != 0) j = lps[j - 1];
            else i++;
        }
    }
    free(lps);
    return match_idx;
}

int rabin_karp_search(const char* text, const char* pat, int q) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    int d = 256;
    int p = 0, t = 0, h = 1;
    for (int i = 0; i < m - 1; i++) h = (h * d) % q;
    for (int i = 0; i < m; i++) {
        p = (d * p + pat[i]) % q;
        t = (d * t + text[i]) % q;
    }
    for (int i = 0; i <= n - m; i++) {
        if (p == t) {
            int match = 1;
            for (int j = 0; j < m; j++) {
                if (text[i + j] != pat[j]) { match = 0; break; }
            }
            if (match) return i;
        }
        if (i < n - m) {
            t = (d * (t - text[i] * h) + text[i + m]) % q;
            if (t < 0) t = t + q;
        }
    }
    return -1;
}

static int expand_center(const char* s, int len, int left, int right) {
    while (left >= 0 && right < len && s[left] == s[right]) {
        left--;
        right++;
    }
    return right - left - 1;
}

void longest_palindromic_substring(const char* str, char* dest) {
    int n = (int)strlen(str);
    if (n <= 0) { dest[0] = '\0'; return; }
    int start = 0, max_len = 1;
    for (int i = 0; i < n; i++) {
        int len1 = expand_center(str, n, i, i);
        int len2 = expand_center(str, n, i, i + 1);
        int len = len1 > len2 ? len1 : len2;
        if (len > max_len) {
            max_len = len;
            start = i - (len - 1) / 2;
        }
    }
    strncpy(dest, str + start, max_len);
    dest[max_len] = '\0';
}

