static int linear_search(const int* arr, int n, int target, int* comps) {
    *comps = 0;
    for (int i = 0; i < n; i++) {
        (*comps)++;
        if (arr[i] == target) return i;
    }
    return -1;
}

static int sentinel_search(int* arr, int n, int target, int* comps) {
    *comps = 0;
    int last = arr[n - 1];
    arr[n - 1] = target;
    int i = 0;
    while (arr[i] != target) {
        (*comps)++;
        i++;
    }
    arr[n - 1] = last;
    (*comps)++;
    if (i < n - 1 || arr[n - 1] == target) return i;
    return -1;
}

