static void fractional_knapsack(void) {
    int n;
    double capacity;
    printf("Enter number of items N and Knapsack Capacity W: ");
    if (scanf("%d %lf", &n, &capacity) != 2 || n <= 0 || capacity <= 0 || n > MAX_ITEMS) {
        clear_input();
