        swap_char(&str[l], &str[i]);
    }
}

static void power_set(const char* str, char* current, int idx, int curr_len, int n) {
    if (idx == n) {
        current[curr_len] = '\0';
        printf("{ %s }\n", current);
        return;
    }
    current[curr_len] = str[idx];
    power_set(str, current, idx + 1, curr_len + 1, n);
    power_set(str, current, idx + 1, curr_len, n);
}

