static void compute_lps(const char* pat, int m, int* lps) {
    int len = 0;
    lps[0] = 0;
    int i = 1;
    while (i < m) {
        if (pat[i] == pat[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
    }
}

static void kmp_search(const char* text, const char* pat) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    int lps[MAX_PAT];
    compute_lps(pat, m, lps);
    printf("LPS Array: ");
    for (int i = 0; i < m; i++) printf("%d ", lps[i]);
    putchar('\n');
    int i = 0, j = 0, count = 0;
    printf("Pattern found at indices: ");
    while (i < n) {
        if (pat[j] == text[i]) {
            i++; j++;
        }
        if (j == m) {
            printf("%d ", i - j);
            count++;
            j = lps[j - 1];
        } else if (i < n && pat[j] != text[i]) {
            if (j != 0) j = lps[j - 1];
            else i++;
        }
    }
    if (count == 0) printf("None");
    printf("\nTotal Matches: %d\n", count);
}

