int cp_coordinate_compress(int* arr, int n, int* unique_arr) {
    for (int i = 0; i < n; i++) {
        unique_arr[i] = arr[i];
    }
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (unique_arr[j] > unique_arr[j + 1]) {
                int tmp = unique_arr[j];
                unique_arr[j] = unique_arr[j + 1];
                unique_arr[j + 1] = tmp;
            }
        }
    }
    int u = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || unique_arr[i] != unique_arr[i - 1]) {
            unique_arr[u++] = unique_arr[i];
        }
    }
    return u;
}

int cp_compressed_rank(const int* unique_arr, int size, int val) {
    int low = 0, high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (unique_arr[mid] == val) return mid;
        if (unique_arr[mid] < val) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int cp_bit_count_set(unsigned int n) {
    int count = 0;
    while (n > 0) {
        n &= (n - 1);
        count++;
    }
    return count;
}

int cp_bit_iterate_submasks(int mask, int* out_submasks, int max_capacity) {
    int count = 0;
    for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
        if (count < max_capacity) {
            out_submasks[count++] = sub;
        }
    }
    return count;
}

int cp_bitmask_has_subset(int supermask, int submask) {
    return (supermask & submask) == submask;
}

void cp_sieve_eratosthenes(int n, char* is_prime) {
    for (int i = 0; i <= n; i++) is_prime[i] = 1;
    is_prime[0] = 0;
    if (n >= 1) is_prime[1] = 0;
    for (int p = 2; p * p <= n; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= n; i += p) {
                is_prime[i] = 0;
            }
        }
    }
}

int cp_prime_factorization(long long n, long long* primes, int* exponents) {
    int count = 0;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            primes[count] = d;
            exponents[count] = 0;
            while (n % d == 0) {
                exponents[count]++;
                n /= d;
            }
            count++;
        }
    }
    if (n > 1) {
        primes[count] = n;
        exponents[count] = 1;
        count++;
    }
    return count;
}

long long cp_mod_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long cp_extended_gcd(long long a, long long b, long long* x, long long* y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }
    long long x1, y1;
    long long gcd = cp_extended_gcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return gcd;
}

long long cp_mod_inverse(long long a, long long mod) {
    long long x, y;
    long long g = cp_extended_gcd(a, mod, &x, &y);
    if (g != 1) return -1;
    return (x % mod + mod) % mod;
}

void cp_precompute_factorials(int n, long long mod, long long* fact, long long* inv_fact) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
    inv_fact[n] = cp_mod_pow(fact[n], mod - 2, mod);
    for (int i = n - 1; i >= 0; i--) {
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod;
    }
}

long long cp_ncr_modulo(int n, int r, long long mod, const long long* fact, const long long* inv_fact) {
    if (r < 0 || r > n) return 0;
    long long num = fact[n];
    long long den = (inv_fact[r] * inv_fact[n - r]) % mod;
    return (num * den) % mod;
}

void cp_matrix_multiply_2x2(const long long A[2][2], const long long B[2][2], long long C[2][2], long long mod) {
    long long r00 = (A[0][0] * B[0][0] + A[0][1] * B[1][0]) % mod;
    long long r01 = (A[0][0] * B[0][1] + A[0][1] * B[1][1]) % mod;
    long long r10 = (A[1][0] * B[0][0] + A[1][1] * B[1][0]) % mod;
    long long r11 = (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % mod;
    C[0][0] = r00;
    C[0][1] = r01;
    C[1][0] = r10;
    C[1][1] = r11;
}

long long cp_matrix_power_fibonacci(long long n, long long mod) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    long long res[2][2] = {{1, 0}, {0, 1}};
    long long base[2][2] = {{1, 1}, {1, 0}};
    long long p = n - 1;
    while (p > 0) {
        if (p & 1) {
            long long tmp[2][2];
            cp_matrix_multiply_2x2(res, base, tmp, mod);
            res[0][0] = tmp[0][0]; res[0][1] = tmp[0][1];
            res[1][0] = tmp[1][0]; res[1][1] = tmp[1][1];
        }
        long long tmp_base[2][2];
        cp_matrix_multiply_2x2(base, base, tmp_base, mod);
        base[0][0] = tmp_base[0][0]; base[0][1] = tmp_base[0][1];
        base[1][0] = tmp_base[1][0]; base[1][1] = tmp_base[1][1];
        p >>= 1;
    }
    return res[0][0];
}

void cp_prefix_sum_1d_build(const int* arr, int n, long long* pref) {
    pref[0] = 0;
    for (int i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + arr[i];
    }
}

long long cp_prefix_sum_1d_query(const long long* pref, int L, int R) {
    return pref[R + 1] - pref[L];
}

long long cp_prefix_sum_2d_query(const long long* pref, int cols_stride, int r1, int c1, int r2, int c2) {
    long long total = pref[(r2 + 1) * cols_stride + (c2 + 1)];
    long long top = pref[r1 * cols_stride + (c2 + 1)];
    long long left = pref[(r2 + 1) * cols_stride + c1];
    long long diag = pref[r1 * cols_stride + c1];
    return total - top - left + diag;
}

void cp_difference_array_range_add(long long* diff, int L, int R, long long val) {
    diff[L] += val;
    diff[R + 1] -= val;
}

void cp_difference_array_compute(const long long* diff, int n, long long* res) {
    long long running = 0;
    for (int i = 0; i < n; i++) {
        running += diff[i];
        res[i] = running;
    }
}

int cp_two_pointers_pair_sum(const int* arr, int n, int target, int* out_i, int* out_j) {
    int left = 0, right = n - 1;
    while (left < right) {
        int sum = arr[left] + arr[right];
        if (sum == target) {
            *out_i = left;
            *out_j = right;
            return 1;
        }
        if (sum < target) left++;
        else right--;
    }
    return 0;
}

int cp_two_pointers_remove_duplicates(int* arr, int n) {
    if (n <= 1) return n;
    int slow = 0;
    for (int fast = 1; fast < n; fast++) {
        if (arr[fast] != arr[slow]) {
            slow++;
            arr[slow] = arr[fast];
        }
    }
    return slow + 1;
}

long long cp_two_pointers_trapping_rain_water(const int* heights, int n) {
    if (n <= 2) return 0;
    int left = 0, right = n - 1;
    int left_max = 0, right_max = 0;
    long long total_water = 0;
    while (left <= right) {
        if (heights[left] <= heights[right]) {
            if (heights[left] >= left_max) left_max = heights[left];
            else total_water += (left_max - heights[left]);
            left++;
        } else {
            if (heights[right] >= right_max) right_max = heights[right];
            else total_water += (right_max - heights[right]);
            right--;
        }
    }
    return total_water;
}

long long cp_sliding_window_fixed_sum(const int* arr, int n, int k) {
    if (n < k || k <= 0) return 0;
    long long current_sum = 0;
    for (int i = 0; i < k; i++) current_sum += arr[i];
    long long max_sum = current_sum;
    for (int i = k; i < n; i++) {
        current_sum += arr[i] - arr[i - k];
        if (current_sum > max_sum) max_sum = current_sum;
    }
    return max_sum;
}

int cp_sliding_window_min_subarray_len(const int* arr, int n, long long target) {
    int min_len = n + 1;
    long long current_sum = 0;
    int left = 0;
    for (int right = 0; right < n; right++) {
        current_sum += arr[right];
        while (current_sum >= target) {
            int len = right - left + 1;
            if (len < min_len) min_len = len;
            current_sum -= arr[left++];
        }
    }
    return (min_len <= n) ? min_len : 0;
}

typedef struct CpFenwickTree {
    long long* tree;
    int size;
} CpFenwickTree;

void cp_fenwick_update(CpFenwickTree* ft, int idx, long long delta) {
    while (idx <= ft->size) {
        ft->tree[idx] += delta;
        idx += (idx & (-idx));
    }
}

long long cp_fenwick_query(const CpFenwickTree* ft, int idx) {
    long long sum = 0;
    while (idx > 0) {
        sum += ft->tree[idx];
        idx -= (idx & (-idx));
    }
    return sum;
}

typedef struct CpSegmentTree {
    long long* tree;
    int n;
} CpSegmentTree;

void cp_seg_tree_build(CpSegmentTree* st, const int* arr, int node, int start, int end) {
    if (start == end) {
        st->tree[node] = arr[start];
        return;
    }
    int mid = start + (end - start) / 2;
    cp_seg_tree_build(st, arr, 2 * node, start, mid);
    cp_seg_tree_build(st, arr, 2 * node + 1, mid + 1, end);
    st->tree[node] = (st->tree[2 * node] < st->tree[2 * node + 1]) ? st->tree[2 * node] : st->tree[2 * node + 1];
}

void cp_seg_tree_update(CpSegmentTree* st, int node, int start, int end, int idx, long long val) {
    if (start == end) {
        st->tree[node] = val;
        return;
    }
    int mid = start + (end - start) / 2;
    if (idx <= mid) cp_seg_tree_update(st, 2 * node, start, mid, idx, val);
    else cp_seg_tree_update(st, 2 * node + 1, mid + 1, end, idx, val);
    st->tree[node] = (st->tree[2 * node] < st->tree[2 * node + 1]) ? st->tree[2 * node] : st->tree[2 * node + 1];
}

long long cp_seg_tree_query(const CpSegmentTree* st, int node, int start, int end, int l, int r) {
    if (r < start || end < l) return 9223372036854775807LL;
    if (l <= start && end <= r) return st->tree[node];
    int mid = start + (end - start) / 2;
    long long left_min = cp_seg_tree_query(st, 2 * node, start, mid, l, r);
    long long right_min = cp_seg_tree_query(st, 2 * node + 1, mid + 1, end, l, r);
    return (left_min < right_min) ? left_min : right_min;
}

typedef struct CpDsu {
    int* parent;
    int* rank;
    int size;
} CpDsu;

void cp_dsu_init(CpDsu* dsu, int n, int* parent_buf, int* rank_buf) {
    dsu->parent = parent_buf;
    dsu->rank = rank_buf;
    dsu->size = n;
    for (int i = 0; i < n; i++) {
        dsu->parent[i] = i;
        dsu->rank[i] = 0;
    }
}

int cp_dsu_find(CpDsu* dsu, int i) {
    if (dsu->parent[i] == i) return i;
    dsu->parent[i] = cp_dsu_find(dsu, dsu->parent[i]);
    return dsu->parent[i];
}

int cp_dsu_union(CpDsu* dsu, int i, int j) {
    int root_i = cp_dsu_find(dsu, i);
    int root_j = cp_dsu_find(dsu, j);
    if (root_i == root_j) return 0;
    if (dsu->rank[root_i] < dsu->rank[root_j]) {
        dsu->parent[root_i] = root_j;
    } else if (dsu->rank[root_i] > dsu->rank[root_j]) {
        dsu->parent[root_j] = root_i;
    } else {
        dsu->parent[root_j] = root_i;
        dsu->rank[root_i]++;
    }
    return 1;
}

void cp_monotonic_stack_next_greater(const int* arr, int n, int* next_idx) {
    int stack[n];
    int top = -1;
    for (int i = 0; i < n; i++) next_idx[i] = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && arr[i] > arr[stack[top]]) {
            next_idx[stack[top--]] = i;
        }
        stack[++top] = i;
    }
}

void cp_monotonic_sliding_window_max(const int* arr, int n, int k, int* out_max) {
    int deque[n];
    int head = 0, tail = 0;
    int out_idx = 0;
    for (int i = 0; i < n; i++) {
        if (head < tail && deque[head] <= i - k) head++;
        while (head < tail && arr[deque[tail - 1]] <= arr[i]) tail--;
        deque[tail++] = i;
        if (i >= k - 1) {
            out_max[out_idx++] = arr[deque[head]];
        }
    }
}

long long cp_binary_search_answer_min(long long low, long long high, int (*predicate)(long long, void*), void* context) {
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (predicate(mid, context)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

long long cp_binary_search_answer_max(long long low, long long high, int (*predicate)(long long, void*), void* context) {
    long long ans = low;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (predicate(mid, context)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

long long cp_ternary_search_unimodal_max(long long low, long long high, long long (*f)(long long)) {
    while (high - low >= 3) {
        long long m1 = low + (high - low) / 3;
        long long m2 = high - (high - low) / 3;
        if (f(m1) < f(m2)) low = m1;
        else high = m2;
    }
    long long best_x = low;
    long long best_val = f(low);
    for (long long x = low + 1; x <= high; x++) {
        long long val = f(x);
        if (val > best_val) {
            best_val = val;
            best_x = x;
        }
    }
    return best_x;
}

void cp_zero_one_bfs(int n, const int* head, const int* to, const int* weight, const int* next, int src, int* dist) {
    for (int i = 0; i < n; i++) dist[i] = 1000000000;
    int deque[2 * n + 5];
    int front = n + 2, back = n + 2;
    dist[src] = 0;
    deque[back++] = src;
    while (front < back) {
        int u = deque[front++];
        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            int w = weight[e];
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (w == 0) deque[--front] = v;
                else deque[back++] = v;
            }
        }
    }
}

void cp_lca_binary_lifting_build(int n, int max_log, const int* parent, int* up) {
    for (int i = 0; i < n; i++) {
        up[i * max_log + 0] = parent[i];
    }
    for (int j = 1; j < max_log; j++) {
        for (int i = 0; i < n; i++) {
            int p = up[i * max_log + (j - 1)];
            if (p != -1) up[i * max_log + j] = up[p * max_log + (j - 1)];
            else up[i * max_log + j] = -1;
        }
    }
}

int cp_lca_query(int u, int v, int max_log, const int* depth, const int* up) {
    if (depth[u] < depth[v]) {
        int tmp = u; u = v; v = tmp;
    }
    for (int j = max_log - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) {
            u = up[u * max_log + j];
        }
    }
    if (u == v) return u;
    for (int j = max_log - 1; j >= 0; j--) {
        if (up[u * max_log + j] != up[v * max_log + j]) {
            u = up[u * max_log + j];
            v = up[v * max_log + j];
        }
    }
    return up[u * max_log + 0];
}

void cp_tarjan_scc(int u, const int* head, const int* to, const int* next, int* disc, int* low, int* in_stack, int* stack, int* top, int* timer, int* scc_id, int* scc_count) {
    disc[u] = low[u] = ++(*timer);
    stack[++(*top)] = u;
    in_stack[u] = 1;
    for (int e = head[u]; e != -1; e = next[e]) {
        int v = to[e];
        if (disc[v] == 0) {
            cp_tarjan_scc(v, head, to, next, disc, low, in_stack, stack, top, timer, scc_id, scc_count);
            if (low[v] < low[u]) low[u] = low[v];
        } else if (in_stack[v]) {
            if (disc[v] < low[u]) low[u] = disc[v];
        }
    }
    if (low[u] == disc[u]) {
        (*scc_count)++;
        while (1) {
            int node = stack[(*top)--];
            in_stack[node] = 0;
            scc_id[node] = *scc_count;
            if (node == u) break;
        }
    }
}

