static void fast_write_int(int n) {
    if (n == 0) {
        putchar('0');
        return;
    }
    if (n < 0) {
        putchar('-');
        n = -n;
    }
    char buf[16];
    int idx = 0;
    while (n > 0) {
        buf[idx++] = (char)('0' + (n % 10));
        n /= 10;
    }
    while (idx > 0) {
        putchar(buf[--idx]);
    }
}

static void fast_write_ll(ll n) {
    if (n == 0) {
        putchar('0');
        return;
    }
    if (n < 0) {
        putchar('-');
        n = -n;
    }
    char buf[32];
    int idx = 0;
    while (n > 0) {
        buf[idx++] = (char)('0' + (n % 10));
        n /= 10;
    }
    while (idx > 0) {
        putchar(buf[--idx]);
    }
}

