                } else {
                    clear_input();
                    printf("Value out of sieve range.\n");
                }
                break;
            }
            case 2: {
                int val;
                printf("Enter number: ");
                if (scanf("%d", &val) == 1 && val >= 1 && val <= limit) {
                    clear_input();
                    factorize_spf(val);
                } else {
                    clear_input();
                    printf("Value out of sieve range.\n");
                }
                break;
            }
            case 3: {
                int l, r;
                printf("Enter range L R: ");
                if (scanf("%d %d", &l, &r) == 2 && l <= r && r <= limit) {
                    clear_input();
                    printf("Total primes in [%d, %d]: %d\n", l, r, count_primes_range(l, r));
                } else {
                    clear_input();
                }
                break;
            }
            case 4: {
                int l, r;
                printf("Enter range L R: ");
                if (scanf("%d %d", &l, &r) == 2 && l <= r && r <= limit) {
                    clear_input();
                    printf("Primes in [%d, %d]: ", l, r);
                    int printed = 0;
                    for (int i = l > 2 ? l : 2; i <= r; i++) {
                        if (is_prime[i]) {
                            printf("%d ", i);
                            printed++;
                            if (printed >= 50) {
                                printf("... (truncated)");
                                break;
                            }
                        }
                    }
                    putchar('\n');
                } else {
                    clear_input();
                }
                break;
            }
            case 5: {
                int val;
                printf("Enter N: ");
                if (scanf("%d", &val) == 1 && val >= 1 && val <= limit) {
                    clear_input();
                    printf("phi(%d) = %d\n", val, euler_totient(val));
                } else {
                    clear_input();
                }
                break;
            }
            case 6: {
                int new_lim;
                printf("Enter new limit (<= %d): ", MAX_SIEVE);
                if (scanf("%d", &new_lim) == 1 && new_lim >= 10 && new_lim <= MAX_SIEVE) {
                    clear_input();
                    limit = new_lim;
                    build_sieve(limit);
                    printf("Sieve rebuilt up to %d.\n", limit);
                } else {
                    clear_input();
                }
                break;
            }
            case 7: {
                int t;
                printf("Enter T test cases: ");
                if (scanf("%d", &t) == 1 && t > 0) {
                    clear_input();
                    for (int c = 1; c <= t; c++) {
                        int num;
