            scanf("%d %lld", &idx, &val);
            if (idx >= 1 && idx <= seg_n) update_seg(1, 1, seg_n, idx, val);
        } else if (type == 2) {
            int l, r;
            scanf("%d %d", &l, &r);
            printf("Sum[%d..%d] = %lld\n", l, r, query_sum(1, 1, seg_n, l, r));
        } else if (type == 3) {
            int l, r;
            scanf("%d %d", &l, &r);
            printf("RMQ[%d..%d] = %lld\n", l, r, query_min(1, 1, seg_n, l, r));
        }
    }
    clear_input();
}

