                    clear_input();
                    n = 3;
                    break;
                }
                printf("Enter %d x %d matrix entries:\n", n, n);
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (scanf("%lf", &a[i][j]) != 1) a[i][j] = 0.0;
                    }
                }
                printf("Enter RHS vector b (%d values): ", n);
                for (int i = 0; i < n; i++) {
                    if (scanf("%lf", &b[i]) != 1) b[i] = 0.0;
                }
                clear_input();
                break;
            }
            case 2:
                if (doolittle_lu(n, a, l, u)) {
