                    for (int i = 0; i < n; i++) det *= u[i][i];
                    printf("Determinant det(A) = Product(U_ii) = %.6f\n", det);
                }
                break;
            case 0:
                printf("Exiting LU Decomposition Workbench.\n");
                break;
            default:
                printf("Invalid selection.\n");
        }
    } while (choice != 0);

