static double eval_lagrange(int n, const double x[], const double y[], double q) {
    double result = 0.0;
    printf("\nLagrange Basis Polynomials at x = %.4f:\n", q);
    for (int i = 0; i < n; i++) {
        double term = 1.0;
        for (int j = 0; j < n; j++) {
            if (i != j) {
                term *= (q - x[j]) / (x[i] - x[j]);
            }
        }
        printf("  L_%d(%.4f) = %10.6f (weighted: y_%d * L_%d = %10.6f)\n",
               i, q, term, i, i, y[i] * term);
        result += y[i] * term;
    }
    return result;
}

