static double double_integral_midpoint(double (*f)(double, double), double ax, double bx, double ay, double by, int nx, int ny) {
    double hx = (bx - ax) / nx;
    double hy = (by - ay) / ny;
    double total = 0.0;

    for (int i = 0; i < nx; i++) {
        double mx = ax + (i + 0.5) * hx;
        for (int j = 0; j < ny; j++) {
            double my = ay + (j + 0.5) * hy;
            total += f(mx, my);
        }
    }
    return total * hx * hy;
}

