                printf("Enter coefficients A B C D E F: ");
                if (scanf("%lf %lf %lf %lf %lf %lf", &A, &B, &C, &D, &E, &F) == 6) {
                    classify_conic(A, B, C, D, E, F);
                } else {
                    clear_input();
                }
                break;
            }
            case 2:
                classify_conic(0.25, 0.0, 1.0 / 9.0, 0.0, 0.0, -1.0);
                break;
            case 3:
                classify_conic(1.0, 0.0, -1.0, 0.0, 0.0, -1.0);
