static void run_t_test(int n, double x_bar, double s, double mu0) {
    if (n <= 1 || s <= 0.0) {
        printf("Error: Sample size must be > 1 and std dev > 0.\n");
        return;
    }

    double se = s / sqrt((double)n);
    double t_stat = (x_bar - mu0) / se;
    int df = n - 1;

    double t_crit_05 = 2.064;
    double t_crit_01 = 2.797;
    if (df >= 30) { t_crit_05 = 1.960; t_crit_01 = 2.576; }
    else if (df >= 20) { t_crit_05 = 2.086; t_crit_01 = 2.845; }
    else if (df >= 10) { t_crit_05 = 2.228; t_crit_01 = 3.169; }

    printf("\n--- One-Sample Student's t-Test Results ---\n");
    printf("  Sample Size N:             %d\n", n);
    printf("  Degrees of Freedom df:     %d\n", df);
    printf("  Sample Mean x_bar:         %10.4f\n", x_bar);
    printf("  Hypothesized Mean mu0:     %10.4f\n", mu0);
    printf("  Sample Std Deviation s:    %10.4f\n", s);
    printf("  Standard Error SE:         %10.4f\n", se);
    printf("  Calculated t-Statistic:    %10.4f\n", t_stat);

    printf("\nHypothesis Test Decision (Two-Tailed):\n");
    printf("  At alpha = 0.05: Critical t = +-%.3f -> ", t_crit_05);
    if (fabs(t_stat) > t_crit_05) printf("REJECT NULL HYPOTHESIS H0 (Statistically Significant!)\n");
    else printf("FAIL TO REJECT NULL HYPOTHESIS H0 (No significant difference).\n");

    printf("  At alpha = 0.01: Critical t = +-%.3f -> ", t_crit_01);
    if (fabs(t_stat) > t_crit_01) printf("REJECT NULL HYPOTHESIS H0 (Highly Significant!)\n");
    else printf("FAIL TO REJECT NULL HYPOTHESIS H0.\n");

    printf("\n95%% Confidence Interval for Population Mean mu:\n");
    printf("  [%.4f, %.4f]\n", x_bar - t_crit_05 * se, x_bar + t_crit_05 * se);
}

int main(void) {
    int choice;
    do {
        printf("\n================ STUDENT'S t-TEST HYPOTHESIS WORKBENCH ================\n");
        printf("1. Perform One-Sample t-Test from Sample Summary (N, mean, std, mu0)\n");
        printf("2. Test Classroom Example (N=25, x_bar=104.2, s=8.5, mu0=100.0)\n");
        printf("0. Exit\n");
        printf("Enter choice: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            continue;
        }

        switch (choice) {
            case 1: {
                int n;
                double x_bar, s, mu0;
                printf("Enter sample size N: ");
                if (scanf("%d", &n) != 1) { clear_input(); break; }
                printf("Enter sample mean x_bar and sample std dev s: ");
                if (scanf("%lf %lf", &x_bar, &s) != 2) { clear_input(); break; }
                printf("Enter hypothesized population mean mu0: ");
                if (scanf("%lf", &mu0) != 1) { clear_input(); break; }
                run_t_test(n, x_bar, s, mu0);
                break;
            }
            case 2:
                run_t_test(25, 104.2, 8.5, 100.0);
                break;
            case 0:
                printf("Exiting Student's t-Test.\n");
                break;
            default:
                printf("Invalid selection.\n");
        }
    } while (choice != 0);

    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_STUDENTS 100

typedef struct {
    int id;
    char name[32];
    double marks[3];
    double gpa;
} Student;

static Student db[MAX_STUDENTS];
static int student_count = 0;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static double calc_gpa(const double m[3]) {
    return ((m[0] + m[1] + m[2]) / 300.0) * 4.0;
}

static void add_student(void) {
    if (student_count >= MAX_STUDENTS) {
        printf("Database full.\n");
        return;
    }
    Student s;
    printf("Enter Student ID: ");
    if (scanf("%d", &s.id) != 1) {
        clear_input();
        return;
    }
    clear_input();
    printf("Enter Student Name: ");
    if (scanf("%31[^\n]", s.name) != 1) {
        clear_input();
        return;
    }
    clear_input();
    printf("Enter 3 course marks (0 to 100): ");
    if (scanf("%lf %lf %lf", &s.marks[0], &s.marks[1], &s.marks[2]) != 3) {
        clear_input();
        return;
    }
    clear_input();
    s.gpa = calc_gpa(s.marks);
    db[student_count++] = s;
    printf("Student added successfully. GPA: %.2f\n", s.gpa);
}

static void display_all_students(void) {
    if (student_count == 0) {
        printf("No records found.\n");
        return;
    }
    printf("%-6s | %-16s | %-6s | %-18s\n", "ID", "Name", "GPA", "Marks [M1, M2, M3]");
    printf("------------------------------------------------------------\n");
    for (int i = 0; i < student_count; i++) {
        printf("%-6d | %-16s | %-6.2f | [%.0f, %.0f, %.0f]\n",
               db[i].id, db[i].name, db[i].gpa, db[i].marks[0], db[i].marks[1], db[i].marks[2]);
    }
}

static void search_student_id(void) {
    int q_id;
    printf("Enter ID to search: ");
    if (scanf("%d", &q_id) != 1) {
        clear_input();
        return;
    }
    clear_input();
    for (int i = 0; i < student_count; i++) {
        if (db[i].id == q_id) {
            printf("Found: ID %d | Name: %s | GPA: %.2f\n", db[i].id, db[i].name, db[i].gpa);
            return;
        }
    }
    printf("Student with ID %d not found.\n", q_id);
}

static void rank_by_gpa(void) {
    if (student_count < 2) return;
    for (int i = 0; i < student_count - 1; i++) {
        for (int j = 0; j < student_count - i - 1; j++) {
            if (db[j].gpa < db[j + 1].gpa) {
                Student tmp = db[j]; db[j] = db[j + 1]; db[j + 1] = tmp;
            }
        }
    }
    printf("Ranked students by GPA descending:\n");
    display_all_students();
}

int main(void) {
    int choice;
    do {
        printf("=== Student Record Management System ===\n");
        printf("1. Add New Student Record\n");
        printf("2. View All Student Records\n");
        printf("3. Search Student by ID\n");
        printf("4. Rank Students by GPA\n");
        printf("0. Exit\n");
        printf("Enter choice: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            choice = -1;
            continue;
        }
        clear_input();
        switch (choice) {
            case 1:
                add_student();
                break;
            case 2:
                display_all_students();
                break;
            case 3:
                search_student_id();
                break;
            case 4:
                rank_by_gpa();
                break;
            case 0:
                printf("Exiting system.\n");
                break;
            default:
                printf("Invalid option.\n");
                break;
        }
    } while (choice != 0);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_ACCOUNTS 50

typedef struct {
    int acc_no;
    char holder[32];
    double balance;
} Account;

static Account accounts[MAX_ACCOUNTS];
static int total_accounts = 0;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static Account* find_account(int no) {
    for (int i = 0; i < total_accounts; i++) {
        if (accounts[i].acc_no == no) return &accounts[i];
    }
    return NULL;
}

static void create_account(void) {
    if (total_accounts >= MAX_ACCOUNTS) {
        printf("Max accounts limit reached.\n");
        return;
    }
    Account a;
    printf("Enter new Account Number: ");
    if (scanf("%d", &a.acc_no) != 1) {
        clear_input();
        return;
    }
    clear_input();
    if (find_account(a.acc_no) != NULL) {
        printf("Account number already exists.\n");
        return;
    }
    printf("Enter Account Holder Name: ");
    if (scanf("%31[^\n]", a.holder) != 1) {
        clear_input();
        return;
    }
    clear_input();
    printf("Enter Initial Deposit: ");
    if (scanf("%lf", &a.balance) != 1 || a.balance < 0) {
        clear_input();
        return;
    }
    clear_input();
    accounts[total_accounts++] = a;
    printf("Account #%d created successfully.\n", a.acc_no);
}

static void deposit(void) {
    int no;
    double amt;
    printf("Enter Account Number: ");
    if (scanf("%d", &no) != 1) {
        clear_input();
        return;
    }
    Account* a = find_account(no);
    if (!a) {
        printf("Account not found.\n");
        clear_input();
        return;
    }
    printf("Enter Deposit Amount: ");
    if (scanf("%lf", &amt) != 1 || amt <= 0) {
        clear_input();
        return;
    }
    clear_input();
    a->balance += amt;
    printf("Deposited $%.2f. New Balance: $%.2f\n", amt, a->balance);
}

static void withdraw(void) {
    int no;
    double amt;
    printf("Enter Account Number: ");
    if (scanf("%d", &no) != 1) {
        clear_input();
        return;
    }
    Account* a = find_account(no);
    if (!a) {
        printf("Account not found.\n");
        clear_input();
        return;
    }
    printf("Enter Withdrawal Amount: ");
    if (scanf("%lf", &amt) != 1 || amt <= 0) {
        clear_input();
        return;
    }
    clear_input();
    if (a->balance < amt) {
        printf("Insufficient balance ($%.2f).\n", a->balance);
        return;
    }
    a->balance -= amt;
    printf("Withdrawn $%.2f. Remaining Balance: $%.2f\n", amt, a->balance);
}

static void transfer(void) {
    int src_no, dst_no;
    double amt;
    printf("Enter Source and Destination Account Numbers: ");
    if (scanf("%d %d", &src_no, &dst_no) != 2) {
        clear_input();
        return;
    }
    Account* src = find_account(src_no);
    Account* dst = find_account(dst_no);
    if (!src || !dst) {
        printf("One or both accounts not found.\n");
        clear_input();
        return;
    }
    printf("Enter Transfer Amount: ");
    if (scanf("%lf", &amt) != 1 || amt <= 0) {
        clear_input();
        return;
    }
    clear_input();
    if (src->balance < amt) {
        printf("Insufficient balance in source account.\n");
        return;
    }
    src->balance -= amt;
    dst->balance += amt;
    printf("Transferred $%.2f from #%d to #%d successfully.\n", amt, src_no, dst_no);
}

static void list_accounts(void) {
    if (total_accounts == 0) {
        printf("No accounts registered.\n");
