            printf("<b>");
            i += 2;
            while (i < len && !(line[i] == '*' && line[i + 1] == '*')) {
                putchar(line[i++]);
            }
            printf("</b>");
            if (i < len) i++;
        } else {
            putchar(line[i]);
        }
    }
    printf("</p>\n");
}

