}

#include <stdio.h>
#include <string.h>

#define MAX_TIMERS 20

typedef void (*Callback)(int id, void* data);

typedef struct {
    int id;
    int ticks_remaining;
    int interval;
    int is_active;
    char name[32];
} Timer;

static Timer timers[MAX_TIMERS];
static int total_timers = 0;
static int current_tick = 0;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static void register_timer(const char* name, int interval) {
    if (total_timers >= MAX_TIMERS) {
        printf("Timer queue full.\n");
        return;
    }
    Timer t;
    t.id = total_timers + 1;
    strncpy(t.name, name, 31);
    t.name[31] = '\0';
    t.interval = interval;
    t.ticks_remaining = interval;
    t.is_active = 1;
    timers[total_timers++] = t;
    printf("Registered timer #%d '%s' with interval %d ticks.\n", t.id, t.name, interval);
}

static void step_event_loop(int steps) {
    for (int s = 0; s < steps; s++) {
        current_tick++;
        printf("[Tick #%d]\n", current_tick);
        int fired = 0;
        for (int i = 0; i < total_timers; i++) {
            if (timers[i].is_active) {
                timers[i].ticks_remaining--;
                if (timers[i].ticks_remaining <= 0) {
                    printf("  >>> Timer #%d ('%s') FIRED callback!\n", timers[i].id, timers[i].name);
                    timers[i].ticks_remaining = timers[i].interval;
                    fired++;
                }
            }
        }
        if (!fired) printf("  (No timers triggered)\n");
    }
}

int main(void) {
    int choice;
    do {
        printf("=== Asynchronous Event Loop Simulator ===\n");
        printf("Current Tick: %d | Active Timers: %d\n", current_tick, total_timers);
        printf("1. Register New Timer\n");
        printf("2. Step Event Loop (Advance Ticks)\n");
        printf("3. List All Timers\n");
        printf("0. Exit\n");
        printf("Enter choice: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            choice = -1;
            continue;
        }
        clear_input();
        switch (choice) {
            case 1: {
                char name[32];
                int interval;
                printf("Enter timer name and tick interval: ");
                if (scanf("%31s %d", name, &interval) == 2 && interval > 0) {
                    clear_input();
                    register_timer(name, interval);
                } else {
                    clear_input();
                }
                break;
            }
            case 2: {
                int steps;
                printf("Enter number of ticks to step: ");
                if (scanf("%d", &steps) == 1 && steps > 0) {
                    clear_input();
                    step_event_loop(steps);
                } else {
                    clear_input();
                }
                break;
            }
            case 3: {
                if (total_timers == 0) {
                    printf("No timers registered.\n");
                    break;
                }
                printf("%-4s | %-16s | %-10s | %-10s\n", "ID", "Name", "Interval", "Next Trigger");
                printf("----------------------------------------------\n");
                for (int i = 0; i < total_timers; i++) {
                    printf("%-4d | %-16s | %-10d | In %d ticks\n",
                           timers[i].id, timers[i].name, timers[i].interval, timers[i].ticks_remaining);
                }
                break;
            }
            case 0:
                printf("Exiting event loop.\n");
                break;
            default:
                printf("Invalid option.\n");
                break;
        }
    } while (choice != 0);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_ENTRIES 50

typedef struct {
    char key[32];
    char val[64];
    int ttl_seconds;
    int is_active;
} Entry;

static Entry store[MAX_ENTRIES];
static int total_entries = 0;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static void kv_set(const char* k, const char* v, int ttl) {
    for (int i = 0; i < total_entries; i++) {
        if (store[i].is_active && strcmp(store[i].key, k) == 0) {
            strncpy(store[i].val, v, 63);
            store[i].ttl_seconds = ttl;
            printf("Updated key '%s'.\n", k);
            return;
        }
    }
    if (total_entries < MAX_ENTRIES) {
        strncpy(store[total_entries].key, k, 31);
        strncpy(store[total_entries].val, v, 63);
        store[total_entries].ttl_seconds = ttl;
        store[total_entries].is_active = 1;
        total_entries++;
        printf("Set key '%s' = '%s'.\n", k, v);
    } else {
        printf("Store full.\n");
    }
}

static void kv_get(const char* k) {
    for (int i = 0; i < total_entries; i++) {
        if (store[i].is_active && strcmp(store[i].key, k) == 0) {
            printf("Value for '%s': '%s' (TTL: %d)\n", k, store[i].val, store[i].ttl_seconds);
            return;
        }
    }
    printf("Key '%s' not found or expired.\n", k);
}

static void kv_tick(int sec) {
    int expired = 0;
    for (int i = 0; i < total_entries; i++) {
        if (store[i].is_active && store[i].ttl_seconds > 0) {
            store[i].ttl_seconds -= sec;
            if (store[i].ttl_seconds <= 0) {
                store[i].is_active = 0;
                printf("Key '%s' expired and purged.\n", store[i].key);
                expired++;
            }
        }
    }
    printf("Advanced time by %d seconds. (%d keys expired)\n", sec, expired);
}

int main(void) {
    int choice;
    do {
        printf("=== In-Memory Key-Value Store with TTL ===\n");
        printf("1. SET key value (no TTL)\n");
        printf("2. SETEX key seconds value (with TTL)\n");
        printf("3. GET key\n");
        printf("4. TICK (Advance Simulated Time)\n");
        printf("5. LIST ALL Active Keys\n");
        printf("0. Exit\n");
        printf("Enter choice: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            choice = -1;
            continue;
        }
        clear_input();
        switch (choice) {
            case 1: {
                char k[32], v[64];
                printf("Enter key and value: ");
                if (scanf("%31s %63s", k, v) == 2) {
                    clear_input();
                    kv_set(k, v, 0);
                } else {
                    clear_input();
                }
                break;
            }
            case 2: {
                char k[32], v[64];
                int ttl;
                printf("Enter key, TTL seconds, and value: ");
                if (scanf("%31s %d %63s", k, &ttl, v) == 3 && ttl > 0) {
                    clear_input();
                    kv_set(k, v, ttl);
                } else {
                    clear_input();
                }
                break;
            }
            case 3: {
                char k[32];
                printf("Enter key: ");
                if (scanf("%31s", k) == 1) {
                    clear_input();
                    kv_get(k);
                } else {
                    clear_input();
                }
                break;
            }
            case 4: {
                int sec;
                printf("Enter seconds to advance: ");
                if (scanf("%d", &sec) == 1 && sec > 0) {
                    clear_input();
                    kv_tick(sec);
                } else {
                    clear_input();
                }
                break;
            }
            case 5: {
                printf("%-16s | %-24s | %-10s\n", "Key", "Value", "TTL");
                printf("--------------------------------------------------\n");
                for (int i = 0; i < total_entries; i++) {
                    if (store[i].is_active) {
                        printf("%-16s | %-24s | %d\n", store[i].key, store[i].val, store[i].ttl_seconds);
                    }
                }
                break;
            }
            case 0:
                printf("Exiting store.\n");
                break;
            default:
                printf("Invalid option.\n");
                break;
        }
    } while (choice != 0);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_LOGS 50

typedef struct {
    int seq_num;
    char operation[16];
    char key[32];
    int val;
    unsigned int checksum;
} WalRecord;

static WalRecord wal[MAX_LOGS];
static int log_count = 0;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static unsigned int simple_crc(const char* str, int val) {
    unsigned int h = 5381;
    for (int i = 0; str[i]; i++) h = ((h << 5) + h) + (unsigned char)str[i];
    h = ((h << 5) + h) + (unsigned int)val;
    return h;
}

static void append_record(const char* op, const char* k, int v) {
    if (log_count >= MAX_LOGS) {
        printf("WAL full.\n");
        return;
    }
    WalRecord r;
    r.seq_num = log_count + 1;
    strncpy(r.operation, op, 15);
    r.operation[15] = '\0';
    strncpy(r.key, k, 31);
    r.key[31] = '\0';
    r.val = v;
    r.checksum = simple_crc(k, v);
    wal[log_count++] = r;
    printf("WAL appended: Seq #%d [%s %s = %d] (Checksum: 0x%08X)\n",
           r.seq_num, r.operation, r.key, r.val, r.checksum);
}

static void replay_wal(void) {
    printf("Replaying WAL for Crash Recovery:\n");
    int valid = 0, corrupted = 0;
    for (int i = 0; i < log_count; i++) {
        unsigned int expected = simple_crc(wal[i].key, wal[i].val);
        if (expected == wal[i].checksum) {
            printf("  [OK] Seq #%d: Apply %s %s = %d\n",
                   wal[i].seq_num, wal[i].operation, wal[i].key, wal[i].val);
            valid++;
        } else {
            printf("  [CORRUPTED] Seq #%d: Checksum mismatch! Skipping.\n", wal[i].seq_num);
            corrupted++;
        }
    }
    printf("Replay finished: %d records applied, %d corrupted.\n", valid, corrupted);
}

int main(void) {
    int choice;
    do {
        printf("=== Write-Ahead Log (WAL) Storage Engine ===\n");
        printf("Active WAL Records: %d\n", log_count);
        printf("1. Append Transaction to WAL\n");
        printf("2. Replay WAL (Crash Recovery Simulator)\n");
        printf("3. Corrupt Last WAL Record (Simulate Bit Rot)\n");
        printf("0. Exit\n");
        printf("Enter choice: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            choice = -1;
            continue;
        }
        clear_input();
        switch (choice) {
            case 1: {
                char op[16], k[32];
                int v;
                printf("Enter Operation (e.g. PUT/ADD), Key, and Value: ");
                if (scanf("%15s %31s %d", op, k, &v) == 3) {
                    clear_input();
                    append_record(op, k, v);
                } else {
                    clear_input();
                }
                break;
            }
            case 2:
                replay_wal();
                break;
            case 3: {
                if (log_count == 0) {
                    printf("WAL is empty.\n");
                    break;
                }
                wal[log_count - 1].checksum ^= 0xFFFFFFFF;
                printf("Corrupted checksum of Seq #%d.\n", wal[log_count - 1].seq_num);
                break;
            }
            case 0:
                printf("Exiting WAL engine.\n");
                break;
            default:
                printf("Invalid option.\n");
                break;
        }
    } while (choice != 0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define T 3

typedef struct BTreeNode {
    int keys[2 * T - 1];
    struct BTreeNode* C[2 * T];
    int n;
    int leaf;
} BTreeNode;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static BTreeNode* create_node(int leaf) {
    BTreeNode* node = (BTreeNode*)malloc(sizeof(BTreeNode));
    node->leaf = leaf;
    node->n = 0;
    for (int i = 0; i < 2 * T; i++) node->C[i] = NULL;
    return node;
}

static void traverse_btree(BTreeNode* root) {
    if (!root) return;
    int i;
    for (i = 0; i < root->n; i++) {
        if (!root->leaf) traverse_btree(root->C[i]);
        printf("%d ", root->keys[i]);
    }
    if (!root->leaf) traverse_btree(root->C[i]);
}

static void split_child(BTreeNode* x, int i, BTreeNode* y) {
    BTreeNode* z = create_node(y->leaf);
    z->n = T - 1;
    for (int j = 0; j < T - 1; j++) z->keys[j] = y->keys[j + T];
    if (!y->leaf) {
        for (int j = 0; j < T; j++) z->C[j] = y->C[j + T];
    }
    y->n = T - 1;
    for (int j = x->n; j >= i + 1; j--) x->C[j + 1] = x->C[j];
    x->C[i + 1] = z;
    for (int j = x->n - 1; j >= i; j--) x->keys[j + 1] = x->keys[j];
    x->keys[i] = y->keys[T - 1];
    x->n++;
}

static void insert_non_full(BTreeNode* x, int k) {
    int i = x->n - 1;
    if (x->leaf) {
        while (i >= 0 && x->keys[i] > k) {
            x->keys[i + 1] = x->keys[i];
            i--;
        }
        x->keys[i + 1] = k;
        x->n++;
    } else {
        while (i >= 0 && x->keys[i] > k) i--;
        i++;
        if (x->C[i]->n == 2 * T - 1) {
            split_child(x, i, x->C[i]);
            if (x->keys[i] < k) i++;
        }
        insert_non_full(x->C[i], k);
    }
}

static BTreeNode* insert_btree(BTreeNode* root, int k) {
    if (!root) {
        root = create_node(1);
        root->keys[0] = k;
        root->n = 1;
        return root;
    }
    if (root->n == 2 * T - 1) {
        BTreeNode* s = create_node(0);
        s->C[0] = root;
        split_child(s, 0, root);
        int i = 0;
        if (s->keys[0] < k) i++;
        insert_non_full(s->C[i], k);
        return s;
    } else {
        insert_non_full(root, k);
        return root;
    }
}

int main(void) {
    int choice;
    BTreeNode* root = NULL;
    do {
        printf("=== B-Tree Indexing Storage Engine (Degree T=3) ===\n");
        printf("1. Insert Key into B-Tree\n");
        printf("2. In-Order Sorted Key Traversal\n");
        printf("0. Exit\n");
        printf("Enter choice: ");
        if (scanf("%d", &choice) != 1) {
            clear_input();
            choice = -1;
            continue;
        }
        clear_input();
        switch (choice) {
            case 1: {
                int key;
                printf("Enter integer key to insert: ");
                if (scanf("%d", &key) == 1) {
                    clear_input();
                    root = insert_btree(root, key);
                    printf("Key %d inserted into B-Tree index.\n", key);
