#include <stdio.h>

#define OP_PUSH 1
#define OP_ADD  2
#define OP_SUB  3
#define OP_MUL  4
#define OP_PRINT 5
#define OP_HALT 6

static int stack[64];
static int sp = -1;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static void run_vm(const int* code, int len) {
    sp = -1;
    int pc = 0;
    while (pc < len) {
        int op = code[pc++];
        if (op == OP_PUSH) {
            stack[++sp] = code[pc++];
        } else if (op == OP_ADD) {
            int b = stack[sp--];
            int a = stack[sp--];
            stack[++sp] = a + b;
        } else if (op == OP_SUB) {
            int b = stack[sp--];
            int a = stack[sp--];
            stack[++sp] = a - b;
        } else if (op == OP_MUL) {
            int b = stack[sp--];
            int a = stack[sp--];
            stack[++sp] = a * b;
        } else if (op == OP_PRINT) {
            printf("VM Output: %d\n", stack[sp]);
        } else if (op == OP_HALT) {
            break;
        }
    }
}

int main(void) {
    int choice;
    do {
        printf("=== Stack Bytecode Virtual Machine ===\n");
        printf("1. Execute Program: (10 + 20) * 3\n");
        printf("2. Execute Custom (A + B) * C\n");
