            }
            case 2: {
                int a, b, c;
                printf("Enter A B C: ");
                if (scanf("%d %d %d", &a, &b, &c) == 3) {
                    clear_input();
                    int code[] = {OP_PUSH, a, OP_PUSH, b, OP_ADD, OP_PUSH, c, OP_MUL, OP_PRINT, OP_HALT};
                    run_vm(code, 10);
                } else {
                    clear_input();
                }
                break;
            }
            case 0:
