        Block* b = (Block*)(heap_mem + offset);
        printf("  [Offset %4d: %s, size %4d bytes]\n",
               offset, b->is_free ? "FREE " : "ALLOC", b->size);
        offset += sizeof(Block) + b->size;
    }
}

