int detect_parity_even(unsigned char byte) {
    int count = 0;
    while (byte) {
        count += (byte & 1);
        byte >>= 1;
    }
    return (count % 2 == 0);
}

int detect_parity_odd(unsigned char byte) {
    int count = 0;
    while (byte) {
        count += (byte & 1);
        byte >>= 1;
    }
    return (count % 2 != 0);
}

int detect_crc8(const unsigned char* data, int len, unsigned char expected) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == expected);
}

int detect_crc16(const unsigned char* data, int len, unsigned short expected) {
    unsigned short crc = 0xFFFF;
    for (int i = 0; i < len; i++) {
        crc ^= (unsigned short)(data[i] << 8);
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ 0x1021;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == expected);
}

int detect_crc32(const unsigned char* data, int len, unsigned int expected) {
    unsigned int crc = 0xFFFFFFFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    return ((crc ^ 0xFFFFFFFF) == expected);
}

int detect_checksum_internet(const unsigned short* buf, int count) {
    unsigned long sum = 0;
    while (count > 1) {
        sum += *buf++;
        count -= 2;
    }
    if (count > 0) {
        sum += *(const unsigned char*)buf;
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ((unsigned short)(~sum) == 0);
}

int detect_adler32(const unsigned char* data, int len, unsigned int expected) {
    unsigned int a = 1, b = 0;
    for (int i = 0; i < len; i++) {
        a = (a + data[i]) % 65521;
        b = (b + a) % 65521;
    }
    return (((b << 16) | a) == expected);
}

int detect_fletcher16(const unsigned char* data, int len, unsigned short expected) {
    unsigned short sum1 = 0, sum2 = 0;
    for (int i = 0; i < len; i++) {
        sum1 = (sum1 + data[i]) % 255;
        sum2 = (sum2 + sum1) % 255;
    }
    return (((sum2 << 8) | sum1) == expected);
}

int detect_hamming_single_error(unsigned int codeword, int* error_pos) {
    unsigned int p1 = 0, p2 = 0, p4 = 0;
    for (int i = 1; i <= 7; i++) {
        unsigned int bit = (codeword >> (7 - i)) & 1;
        if (i & 1) p1 ^= bit;
        if (i & 2) p2 ^= bit;
        if (i & 4) p4 ^= bit;
    }
    int syndrome = (p4 << 2) | (p2 << 1) | p1;
    if (error_pos) *error_pos = syndrome;
    return (syndrome != 0);
}

int detect_luhn_checksum(const char* num_str) {
    int len = 0;
    while (num_str[len] != '\0') len++;
    int sum = 0, alternate = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (num_str[i] < '0' || num_str[i] > '9') continue;
        int d = num_str[i] - '0';
        if (alternate) {
            d *= 2;
            if (d > 9) d -= 9;
        }
        sum += d;
        alternate = !alternate;
    }
    return (sum % 10 == 0);
}

typedef struct DetectNode {
    int data;
    struct DetectNode* next;
} DetectNode;

int detect_linked_list_cycle_floyd(const DetectNode* head) {
    if (!head || !head->next) return 0;
    const DetectNode* slow = head;
    const DetectNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return 1;
    }
    return 0;
}

typedef struct DetectNode {
    int data;
    struct DetectNode* next;
} DetectNode;

int detect_linked_list_cycle_brent(const DetectNode* head) {
    if (!head) return 0;
    const DetectNode* slow = head;
    const DetectNode* fast = head->next;
    int power = 1, len = 1;
    while (fast) {
        if (slow == fast) return 1;
        if (power == len) {
            slow = fast;
            power *= 2;
            len = 0;
        }
        fast = fast->next;
        len++;
    }
    return 0;
}

static int dfs_dir_cycle(int u, int n, const int adj[64][64], int vis[64], int rec[64]) {
    vis[u] = 1;
    rec[u] = 1;
    for (int v = 0; v < n; v++) {
        if (adj[u][v]) {
            if (!vis[v] && dfs_dir_cycle(v, n, adj, vis, rec)) return 1;
            else if (rec[v]) return 1;
        }
    }
    rec[u] = 0;
    return 0;
}

int detect_graph_cycle_directed_dfs(int n, const int adj[64][64]) {
    int vis[64] = {0};
    int rec[64] = {0};
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            if (dfs_dir_cycle(i, n, adj, vis, rec)) return 1;
        }
    }
    return 0;
}

int detect_graph_cycle_directed_kahn(int n, const int adj[64][64]) {
    int in_degree[64] = {0};
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (adj[i][j]) in_degree[j]++;
        }
    }
    int queue[64], front = 0, rear = 0;
    for (int i = 0; i < n; i++) {
        if (in_degree[i] == 0) queue[rear++] = i;
    }
    int visited_count = 0;
    while (front < rear) {
        int u = queue[front++];
        visited_count++;
        for (int v = 0; v < n; v++) {
            if (adj[u][v]) {
                in_degree[v]--;
                if (in_degree[v] == 0) queue[rear++] = v;
            }
        }
    }
    return (visited_count != n);
}

static int dfs_undir_cycle(int u, int p, int n, const int adj[64][64], int vis[64]) {
    vis[u] = 1;
    for (int v = 0; v < n; v++) {
        if (adj[u][v]) {
            if (!vis[v]) {
                if (dfs_undir_cycle(v, u, n, adj, vis)) return 1;
            } else if (v != p) {
                return 1;
            }
        }
    }
    return 0;
}

int detect_graph_cycle_undirected_dfs(int n, const int adj[64][64]) {
    int vis[64] = {0};
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            if (dfs_undir_cycle(i, -1, n, adj, vis)) return 1;
        }
    }
    return 0;
}

static int find_ds_root(int parent[], int i) {
    if (parent[i] == -1) return i;
    return parent[i] = find_ds_root(parent, parent[i]);
}

int detect_graph_cycle_disjoint_set(int n, const int edges[][2], int edge_count) {
    int parent[64];
    for (int i = 0; i < n; i++) parent[i] = -1;
    for (int i = 0; i < edge_count; i++) {
        int x = find_ds_root(parent, edges[i][0]);
        int y = find_ds_root(parent, edges[i][1]);
        if (x == y) return 1;
        parent[x] = y;
    }
    return 0;
}

int detect_deadlock_rag(int p, int r, const int alloc[16][16], const int req[16][16], const int avail[16]) {
    int work[16];
    int finish[16] = {0};
    for (int j = 0; j < r; j++) work[j] = avail[j];
    int count = 0;
    while (count < p) {
        int found = 0;
        for (int i = 0; i < p; i++) {
            if (!finish[i]) {
                int can_proceed = 1;
                for (int j = 0; j < r; j++) {
                    if (req[i][j] > work[j]) { can_proceed = 0; break; }
                }
                if (can_proceed) {
                    for (int j = 0; j < r; j++) work[j] += alloc[i][j];
                    finish[i] = 1;
                    found = 1;
                    count++;
                }
            }
        }
        if (!found) break;
    }
    return (count < p);
}

int detect_bipartite_graph(int n, const int adj[64][64]) {
    int color[64];
    for (int i = 0; i < n; i++) color[i] = -1;
    for (int start = 0; start < n; start++) {
        if (color[start] == -1) {
            int queue[64], front = 0, rear = 0;
            queue[rear++] = start;
            color[start] = 0;
            while (front < rear) {
                int u = queue[front++];
                for (int v = 0; v < n; v++) {
                    if (adj[u][v]) {
                        if (color[v] == -1) {
                            color[v] = 1 - color[u];
                            queue[rear++] = v;
                        } else if (color[v] == color[u]) {
                            return 0;
                        }
                    }
                }
            }
        }
    }
    return 1;
}

int detect_eulerian_circuit(int n, const int adj[64][64]) {
    for (int i = 0; i < n; i++) {
        int degree = 0;
        for (int j = 0; j < n; j++) {
            if (adj[i][j]) degree++;
        }
        if (degree % 2 != 0) return 0;
    }
    return 1;
}

int detect_eulerian_path(int n, const int adj[64][64]) {
    int odd_degrees = 0;
    for (int i = 0; i < n; i++) {
        int degree = 0;
        for (int j = 0; j < n; j++) {
            if (adj[i][j]) degree++;
        }
        if (degree % 2 != 0) odd_degrees++;
    }
    return (odd_degrees == 0 || odd_degrees == 2);
}

static void bridge_dfs(int u, int p, int n, const int adj[64][64], int disc[64], int low[64], int* time_step, int* count) {
    disc[u] = low[u] = ++(*time_step);
    for (int v = 0; v < n; v++) {
        if (adj[u][v]) {
            if (v == p) continue;
            if (disc[v]) {
                if (disc[v] < low[u]) low[u] = disc[v];
            } else {
                bridge_dfs(v, u, n, adj, disc, low, time_step, count);
                if (low[v] < low[u]) low[u] = low[v];
                if (low[v] > disc[u]) (*count)++;
            }
        }
    }
}

int detect_bridge_edges(int n, const int adj[64][64]) {
    int disc[64] = {0}, low[64] = {0}, time_step = 0, count = 0;
    for (int i = 0; i < n; i++) {
        if (!disc[i]) bridge_dfs(i, -1, n, adj, disc, low, &time_step, &count);
    }
    return count;
}

static void ap_dfs(int u, int p, int n, const int adj[64][64], int disc[64], int low[64], int is_ap[64], int* time_step) {
    disc[u] = low[u] = ++(*time_step);
    int children = 0;
    for (int v = 0; v < n; v++) {
        if (adj[u][v]) {
            if (v == p) continue;
            if (disc[v]) {
                if (disc[v] < low[u]) low[u] = disc[v];
            } else {
                children++;
                ap_dfs(v, u, n, adj, disc, low, is_ap, time_step);
                if (low[v] < low[u]) low[u] = low[v];
                if (p != -1 && low[v] >= disc[u]) is_ap[u] = 1;
            }
        }
    }
    if (p == -1 && children > 1) is_ap[u] = 1;
}

int detect_articulation_points(int n, const int adj[64][64]) {
    int disc[64] = {0}, low[64] = {0}, is_ap[64] = {0}, time_step = 0;
    for (int i = 0; i < n; i++) {
        if (!disc[i]) ap_dfs(i, -1, n, adj, disc, low, is_ap, &time_step);
    }
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (is_ap[i]) total++;
    }
    return total;
}

static void cc_dfs(int u, int n, const int adj[64][64], int visited[64]) {
    visited[u] = 1;
    for (int v = 0; v < n; v++) {
        if (adj[u][v] && !visited[v]) cc_dfs(v, n, adj, visited);
    }
}

int detect_connected_components(int n, const int adj[64][64]) {
    int visited[64] = {0}, count = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            count++;
            cc_dfs(i, n, adj, visited);
        }
    }
    return count;
}

int detect_dag_property(int n, const int adj[64][64]) {
    int in_degree[64] = {0};
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (adj[i][j]) in_degree[j]++;
        }
    }
    int queue[64], front = 0, rear = 0;
    for (int i = 0; i < n; i++) {
        if (in_degree[i] == 0) queue[rear++] = i;
    }
    int visited = 0;
    while (front < rear) {
        int u = queue[front++];
        visited++;
        for (int v = 0; v < n; v++) {
            if (adj[u][v]) {
                in_degree[v]--;
                if (in_degree[v] == 0) queue[rear++] = v;
            }
        }
    }
    return (visited == n);
}

int detect_palindrome(const char* s) {
    int len = 0;
    while (s[len] != '\0') len++;
    int left = 0, right = len - 1;
    while (left < right) {
        if (s[left] != s[right]) return 0;
        left++;
        right--;
    }
    return 1;
}

int detect_anagram(const char* s1, const char* s2) {
    int count[256] = {0};
    int i = 0;
    while (s1[i] != '\0') { count[(unsigned char)s1[i]]++; i++; }
    int j = 0;
    while (s2[j] != '\0') { count[(unsigned char)s2[j]]--; j++; }
    if (i != j) return 0;
    for (int k = 0; k < 256; k++) {
        if (count[k] != 0) return 0;
    }
    return 1;
}

int detect_pangram(const char* s) {
    int mask = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c >= 'A' && c <= 'Z') mask |= (1 << (c - 'A'));
        else if (c >= 'a' && c <= 'z') mask |= (1 << (c - 'a'));
    }
    return (mask == 0x3FFFFFF);
}

int detect_isogram(const char* s) {
    int seen[256] = {0};
    for (int i = 0; s[i] != '\0'; i++) {
        unsigned char c = (unsigned char)s[i];
        if (seen[c]) return 0;
        seen[c] = 1;
    }
    return 1;
}

int detect_subsequence(const char* pattern, const char* text) {
    int i = 0, j = 0;
    while (pattern[i] != '\0' && text[j] != '\0') {
        if (pattern[i] == text[j]) i++;
        j++;
    }
    return (pattern[i] == '\0');
}

int detect_pattern_kmp(const char* text, const char* pattern) {
    int m = 0;
    while (pattern[m] != '\0') m++;
    if (m == 0) return 0;
    int lps[128] = {0};
    int len = 0, i = 1;
    while (i < m) {
        if (pattern[i] == pattern[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) len = lps[len - 1];
            else { lps[i] = 0; i++; }
        }
    }
    int t_idx = 0, p_idx = 0;
    while (text[t_idx] != '\0') {
        if (pattern[p_idx] == text[t_idx]) {
            p_idx++;
            t_idx++;
        }
        if (p_idx == m) return (t_idx - p_idx);
        else if (text[t_idx] != '\0' && pattern[p_idx] != text[t_idx]) {
            if (p_idx != 0) p_idx = lps[p_idx - 1];
            else t_idx++;
        }
    }
    return -1;
}

int detect_pattern_rabin_karp(const char* text, const char* pattern) {
    int m = 0, n = 0;
    while (pattern[m] != '\0') m++;
    while (text[n] != '\0') n++;
    if (m == 0) return 0;
    if (m > n) return -1;
    const int d = 256, q = 101;
    int p_hash = 0, t_hash = 0, h = 1;
    for (int i = 0; i < m - 1; i++) h = (h * d) % q;
    for (int i = 0; i < m; i++) {
        p_hash = (d * p_hash + pattern[i]) % q;
        t_hash = (d * t_hash + text[i]) % q;
    }
    for (int i = 0; i <= n - m; i++) {
        if (p_hash == t_hash) {
            int match = 1;
            for (int j = 0; j < m; j++) {
                if (text[i + j] != pattern[j]) { match = 0; break; }
            }
            if (match) return i;
        }
        if (i < n - m) {
            t_hash = (d * (t_hash - text[i] * h) + text[i + m]) % q;
            if (t_hash < 0) t_hash += q;
        }
    }
    return -1;
}

int detect_balanced_parentheses(const char* s) {
    char stack[256];
    int top = -1;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '{' || c == '[') {
            if (top >= 255) return 0;
            stack[++top] = c;
        } else if (c == ')' || c == '}' || c == ']') {
            if (top < 0) return 0;
            char o = stack[top--];
            if (c == ')' && o != '(') return 0;
            if (c == '}' && o != '{') return 0;
            if (c == ']' && o != '[') return 0;
        }
    }
    return (top == -1);
}

char detect_repeated_character(const char* s) {
    int seen[256] = {0};
    for (int i = 0; s[i] != '\0'; i++) {
        unsigned char c = (unsigned char)s[i];
        if (seen[c]) return (char)c;
        seen[c] = 1;
    }
    return '\0';
}

int detect_prime(int n) {
    if (n <= 1) return 0;
    if (n <= 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    }
    return 1;
}

int detect_armstrong_number(int n) {
    if (n < 0) return 0;
    int temp = n, digits = 0;
    while (temp > 0) { digits++; temp /= 10; }
    temp = n;
    int sum = 0;
    while (temp > 0) {
        int d = temp % 10;
        int p = 1;
        for (int i = 0; i < digits; i++) p *= d;
        sum += p;
        temp /= 10;
    }
    return (sum == n);
}

int detect_perfect_number(int n) {
    if (n <= 1) return 0;
    int sum = 1;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            sum += i;
            if (i * i != n) sum += (n / i);
        }
    }
    return (sum == n);
}

static int digit_square_sum(int n) {
    int sum = 0;
    while (n > 0) {
        int d = n % 10;
        sum += d * d;
        n /= 10;
    }
    return sum;
}

int detect_happy_number(int n) {
    int slow = n, fast = digit_square_sum(n);
    while (fast != 1 && slow != fast) {
        slow = digit_square_sum(slow);
        fast = digit_square_sum(digit_square_sum(fast));
    }
    return (fast == 1);
}

int detect_overflow_add(int a, int b, int* result) {
    if ((b > 0 && a > 2147483647 - b) || (b < 0 && a < (-2147483647 - 1) - b)) {
        return 1;
    }
    if (result) *result = a + b;
    return 0;
}

int detect_overflow_sub(int a, int b, int* result) {
    if ((b < 0 && a > 2147483647 + b) || (b > 0 && a < (-2147483647 - 1) + b)) {
        return 1;
    }
    if (result) *result = a - b;
    return 0;
}

int detect_overflow_mul(int a, int b, int* result) {
    if (a > 0 && b > 0 && a > 2147483647 / b) return 1;
    if (a > 0 && b < 0 && b < (-2147483647 - 1) / a) return 1;
    if (a < 0 && b > 0 && a < (-2147483647 - 1) / b) return 1;
    if (a < 0 && b < 0 && b < 2147483647 / a) return 1;
    if (result) *result = a * b;
    return 0;
}

int detect_palindrome_number(int n) {
    if (n < 0) return 0;
    int original = n;
    long long rev = 0;
    while (n > 0) {
        rev = rev * 10 + (n % 10);
        n /= 10;
    }
    return (rev == (long long)original);
}

int detect_float_nan(float val) {
    union { float f; unsigned int u; } conv;
    conv.f = val;
    return ((conv.u & 0x7F800000) == 0x7F800000) && ((conv.u & 0x007FFFFF) != 0);
}

int detect_array_sorted_ascending(const int* arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        if (arr[i] > arr[i + 1]) return 0;
    }
    return 1;
}

int detect_array_sorted_descending(const int* arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        if (arr[i] < arr[i + 1]) return 0;
    }
    return 1;
}

int detect_array_monotonic(const int* arr, int n) {
    if (n <= 2) return 1;
    int inc = 1, dec = 1;
    for (int i = 0; i < n - 1; i++) {
        if (arr[i] > arr[i + 1]) inc = 0;
        if (arr[i] < arr[i + 1]) dec = 0;
    }
    return (inc || dec);
}

int detect_array_duplicate(const int* arr, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] == arr[j]) return 1;
        }
    }
    return 0;
}

int detect_array_majority_element(const int* arr, int n, int* majority) {
    int candidate = 0, count = 0;
    for (int i = 0; i < n; i++) {
        if (count == 0) {
            candidate = arr[i];
            count = 1;
        } else if (arr[i] == candidate) {
            count++;
        } else {
            count--;
        }
    }
    int verify = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] == candidate) verify++;
    }
    if (verify > n / 2) {
        if (majority) *majority = candidate;
        return 1;
    }
    return 0;
}

int detect_array_peak_element(const int* arr, int n) {
    if (n <= 0) return -1;
    if (n == 1) return 0;
    if (arr[0] >= arr[1]) return 0;
    for (int i = 1; i < n - 1; i++) {
        if (arr[i] >= arr[i - 1] && arr[i] >= arr[i + 1]) return i;
    }
    if (arr[n - 1] >= arr[n - 2]) return (n - 1);
    return -1;
}

int detect_array_missing_number(const int* arr, int n) {
    int total_xor = 0;
    for (int i = 0; i <= n; i++) total_xor ^= i;
    int arr_xor = 0;
    for (int i = 0; i < n; i++) arr_xor ^= arr[i];
    return (total_xor ^ arr_xor);
}

int detect_array_two_sum_target(const int* arr, int n, int target, int* idx1, int* idx2) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] + arr[j] == target) {
                if (idx1) *idx1 = i;
                if (idx2) *idx2 = j;
                return 1;
            }
        }
    }
    return 0;
}

int detect_aabb_collision_2d(float x1, float y1, float w1, float h1, float x2, float y2, float w2, float h2) {
    return (x1 < x2 + w2 && x1 + w1 > x2 && y1 < y2 + h2 && y1 + h1 > y2);
}

int detect_circle_collision(float x1, float y1, float r1, float x2, float y2, float r2) {
    float dx = x1 - x2;
    float dy = y1 - y2;
    float dist_sq = dx * dx + dy * dy;
    float rad_sum = r1 + r2;
    return (dist_sq <= rad_sum * rad_sum);
}

int detect_point_in_circle(float px, float py, float cx, float cy, float r) {
    float dx = px - cx;
    float dy = py - cy;
    return (dx * dx + dy * dy <= r * r);
}

int detect_point_in_rect(float px, float py, float rx, float ry, float rw, float rh) {
    return (px >= rx && px <= rx + rw && py >= ry && py <= ry + rh);
}

static int ccw_check(float ax, float ay, float bx, float by, float cx, float cy) {
    return ((cy - ay) * (bx - ax) > (by - ay) * (cx - ax));
}

int detect_line_segment_intersection(float x1, float y1, float x2, float y2, float x3, float y3, float x4, float y4) {
    return (ccw_check(x1, y1, x3, y3, x4, y4) != ccw_check(x2, y2, x3, y3, x4, y4)) &&
           (ccw_check(x1, y1, x2, y2, x3, y3) != ccw_check(x1, y1, x2, y2, x4, y4));
}

int detect_point_in_polygon(float px, float py, const float* poly_x, const float* poly_y, int n) {
    int inside = 0;
    for (int i = 0, j = n - 1; i < n; j = i++) {
        if (((poly_y[i] > py) != (poly_y[j] > py)) &&
            (px < (poly_y[j] - poly_x[i]) * (py - poly_y[i]) / (poly_y[j] - poly_y[i]) + poly_x[i])) {
            inside = !inside;
        }
    }
    return inside;
}

int detect_sphere_collision_3d(float x1, float y1, float z1, float r1, float x2, float y2, float z2, float r2) {
    float dx = x1 - x2, dy = y1 - y2, dz = z1 - z2;
    float dist_sq = dx * dx + dy * dy + dz * dz;
    float rad_sum = r1 + r2;
    return (dist_sq <= rad_sum * rad_sum);
}

int detect_ray_box_intersection(float ox, float oy, float dx, float dy, float min_x, float min_y, float max_x, float max_y) {
    float tmin = (min_x - ox) / dx;
    float tmax = (max_x - ox) / dx;
    if (tmin > tmax) { float tmp = tmin; tmin = tmax; tmax = tmp; }
    float tymin = (min_y - oy) / dy;
    float tymax = (max_y - oy) / dy;
    if (tymin > tymax) { float tmp = tymin; tymin = tymax; tymax = tmp; }
    if ((tmin > tymax) || (tymin > tmax)) return 0;
    return 1;
}

int detect_endianness(void) {
    unsigned int x = 0x1;
    char* c = (char*)&x;
    return (int)(*c);
}

int detect_pointer_alignment(const void* ptr, int alignment_bytes) {
    if (alignment_bytes <= 0) return 0;
    return (((unsigned long long)ptr) % (unsigned long long)alignment_bytes == 0);
}

int detect_null_terminator(const char* buf, int max_len) {
    for (int i = 0; i < max_len; i++) {
        if (buf[i] == '\0') return 1;
    }
    return 0;
}

static void stack_check_dir(int* parent_addr, int* out_dir) {
    int local_var;
    if (&local_var < parent_addr) *out_dir = -1;
    else *out_dir = 1;
}

int detect_stack_growth_direction(void) {
    int main_local;
    int direction = 0;
    stack_check_dir(&main_local, &direction);
    return direction;
}
